/* مشكاة · أدعية المناسبات (#adiya) والمناسك والعبادات (#manasik): البيانات ثم العرض؛ يُحمَّل عند أول فتح (يدخل في ذاكرة التطبيق للعمل دون إنترنت). */
window.FQ = {"adiya":{"cats":[["adab","الآداب والجوامع"],["hal","الأحوال والحاجات"],["yawm","اليوم والليلة"],["mawsim","المواسم"]],"ch":[{"id":"adab","c":"adab","t":"آداب الدعاء وأوقات الإجابة","d":"الدعاء عبادة أمر الله بها ووعد عليها بالإجابة، وله آداب وأوقات فاضلة: اليقين والإلحاح، وترك الاستعجال، وثلث الليل الآخر.","ay":[{"t":"وعد الله بالقرب والإجابة","r":[2,186],"n":"جواب سؤال الصحابة: أقريب ربنا فنناجيه؟"},{"t":"«ادعوني أستجب لكم»","r":[40,60],"n":"أمر بالدعاء ووعد بالإجابة، وتحذير من الاستكبار عن عبادته."},{"t":"ادعوه تضرعاً وخفية","r":[7,55,56],"n":"من آداب الدعاء: التضرع والإخفاء، وترك الاعتداء، والخوف والطمع."},{"t":"ادعوه بأسمائه الحسنى","r":[7,180],"n":"أن يتوسل الداعي إلى الله بما يناسب حاجته من أسمائه."}]},{"id":"jawami","c":"adab","t":"جوامع الدعاء","d":"أدعية قليلة اللفظ جامعة للدين والدنيا والآخرة، وكان أكثر دعاء النبي ﷺ: «ربنا آتنا في الدنيا حسنة».","ay":[{"t":"ربنا آتنا في الدنيا حسنة","r":[2,201],"n":"أجمع دعاء في القرآن لخير الدنيا والآخرة والنجاة من النار."},{"t":"ربنا لا تزغ قلوبنا","r":[3,8],"n":"سؤال الثبات على الهداية بعد أن هدى الله."},{"t":"ربنا لا تؤاخذنا","r":[2,286],"n":"خاتمة البقرة: دعاء بالعفو والتيسير ورفع المشقة."},{"t":"ربنا فاغفر لنا ذنوبنا","r":[3,193,194],"n":"من دعاء أولي الألباب: المغفرة والوفاة مع الأبرار ووعد الله الذي لا يخلف."}]},{"id":"istighfar","c":"adab","t":"الاستغفار والتوبة","d":"أقرب الأبواب إلى رحمة الله اعترافٌ بالذنب ورجاء المغفرة؛ وأدعية الأنبياء في هذا الباب مدرسة في الاعتراف والإنابة.","ay":[{"t":"ربنا ظلمنا أنفسنا","r":[7,23],"n":"دعاء آدم وحواء بعد الأكل من الشجرة: اعتراف بالظلم وسؤال المغفرة."},{"t":"رب اغفر وارحم","r":[23,118],"n":"ختام سورة المؤمنون: الأمر بطلب المغفرة والرحمة وأنه خير الراحمين."},{"t":"ربنا أتمم لنا نورنا","r":[66,8],"n":"دعاء المؤمنين يوم القيامة بإتمام النور والمغفرة بعد التوبة النصوح."},{"t":"ربنا إننا آمنا فاغفر لنا","r":[3,16],"n":"من صفات المتقين: التوسل بالإيمان في سؤال المغفرة ووقاية النار."}]},{"id":"karb","c":"hal","t":"الهمّ والكرب والدَّين","d":"أدعية الشدة: دعوة ذي النون في بطن الحوت، ودعاء أيوب، وما علّمه النبي ﷺ لمن ضاق صدره أو أثقله دَين.","ay":[{"t":"دعوة ذي النون","r":[21,87],"n":"نادى يونس ﵇ في الظلمات: لا إله إلا أنت سبحانك إني كنت من الظالمين."},{"t":"دعاء أيوب","r":[21,83,84],"n":"مثال الصبر الجميل: إظهار الحاجة إلى الله دون شكوى للخلق."},{"t":"ربنا أفرغ علينا صبراً","r":[2,250],"n":"دعاء جنود طالوت حين برزوا لجالوت: الصبر وتثبيت الأقدام والنصر."},{"t":"ربنا أفرغ علينا صبراً وتوفنا مسلمين","r":[7,126],"n":"دعاء سحرة فرعون حين هُدّدوا بالقتل بعد إيمانهم."},{"t":"إني لما أنزلت إليّ من خير فقير","r":[28,24],"n":"دعاء موسى ﵇ غريباً جائعاً بعد سقي الغنم، وقد أعقبه الله فرجاً."}]},{"id":"ahl","c":"hal","t":"الأهل والوالدان والذرية","d":"أدعية بر الوالدين، وطلب الذرية الصالحة وقرة العين في الأزواج، من دعوات الأنبياء والصالحين.","ay":[{"t":"رب ارحمهما كما ربياني صغيراً","r":[17,24],"n":"دعاء الولد لوالديه، جزاءً على التربية."},{"t":"هب لنا من أزواجنا وذرياتنا قرة أعين","r":[25,74],"n":"من دعاء عباد الرحمن: صلاح الأسرة وأن يكونوا للمتقين إماماً."},{"t":"رب هب لي من لدنك ذرية طيبة","r":[3,38],"n":"دعاء زكريا ﵇ في المحراب عند مريم."},{"t":"رب اجعلني مقيم الصلاة ومن ذريتي","r":[14,40,41],"n":"دعاء إبراهيم ﵇: إقامة الصلاة له ولذريته ومغفرة الوالدين والمؤمنين."},{"t":"رب أوزعني أن أشكر نعمتك","r":[46,15],"n":"دعاء من بلغ أربعين سنة: الشكر وصلاح الذرية والتوبة."},{"t":"رب اغفر لي ولوالدي","r":[71,28],"n":"ختام دعاء نوح ﵇: المغفرة له ولوالديه ولمن دخل بيته مؤمناً."}]},{"id":"ilm","c":"hal","t":"العلم والهداية والثبات","d":"أدعية طلب العلم النافع، وشرح الصدر وتيسير الأمر، والثبات على الهداية والرشد.","ay":[{"t":"رب اشرح لي صدري ويسر لي أمري","r":[20,25,28],"n":"دعاء موسى ﵇ حين كُلّف بالرسالة: انشراح الصدر وتيسير الأمر وفصاحة اللسان."},{"t":"وقل رب زدني علماً","r":[20,114],"n":"الأمر الوحيد بطلب الزيادة في القرآن هو الزيادة من العلم."},{"t":"ربنا آتنا من لدنك رحمة","r":[18,10],"n":"دعاء الفتية الذين أووا إلى الكهف: الرحمة والرشد."},{"t":"اهدنا الصراط المستقيم","r":[1,6,7],"n":"أعظم دعاء وأكثره تكراراً: تردده كل مسلم في كل ركعة."}]},{"id":"yawm","c":"yawm","t":"النوم والبيت والطعام واللباس","d":"أدعية الحياة اليومية: عند النوم والاستيقاظ، وعند الخروج من البيت، وبعد الطعام وعند اللباس.","ay":[{"t":"سمعنا وأطعنا غفرانك ربنا","r":[2,285],"n":"قول المؤمنين الإذعان لله وسؤال المغفرة والإقرار بأن المصير إليه."}]},{"id":"salat","c":"yawm","t":"الطهارة والمسجد والأذان والصلاة","d":"أدعية الدخول إلى الخلاء والخروج منه، وعند الدخول إلى المسجد، وبعد سماع الأذان، وفي الصلاة وبعدها.","ay":[{"t":"ربنا تقبل منا","r":[2,127,128],"n":"دعاء إبراهيم وإسماعيل ﵉ وهما يرفعان القواعد من البيت."}]},{"id":"safar","c":"yawm","t":"السفر والركوب والنزول","d":"دعاء الركوب وسفر الطاعة، ودعاء المنزل والدخول والخروج، وفيها التماس صحبة الله في السفر.","ay":[{"t":"سبحان الذي سخر لنا هذا","r":[43,13,14],"n":"ذكر نعمة المركوب والإقرار بالضعف والرجوع إلى الله."},{"t":"رب أدخلني مدخل صدق","r":[17,80],"n":"سؤال دخول وخروج على الحق مع سلطان نصير."},{"t":"بسم الله مجراها ومرساها","r":[11,41],"n":"قول نوح ﵇ عند ركوب السفينة."},{"t":"رب أنزلني منزلاً مباركاً","r":[23,29],"n":"دعاء النزول: أن يكون المنزل مباركاً والله خير المنزلين."}]},{"id":"maradh","c":"hal","t":"المرض والعافية","d":"دعاء المريض وللمريض، وسؤال العافية في البدن والسمع والبصر.","ay":[{"t":"وإذا مرضت فهو يشفين","r":[26,78,82],"n":"من كلام إبراهيم ﵇ في الثناء على ربه: الخلق والهداية والإطعام والسقي والشفاء."}]},{"id":"rizq","c":"hal","t":"الرزق والمطر والبركة","d":"دعاء طلب الرزق، والاستسقاء، والدعاء بالبركة في الثمار.","ay":[{"t":"ربنا أنزل علينا مائدة","r":[5,114],"n":"دعاء عيسى ﵇ بنزول المائدة من السماء عيداً وآية ورزقاً."}]},{"id":"mawsim","c":"mawsim","t":"ليلة القدر ويوم عرفة","d":"أدعية المواسم الفاضلة: ليلة القدر في العشر الأواخر من رمضان، ويوم عرفة. وللحج والعمرة أدعية مخصوصة في قسم المناسك.","ay":[{"t":"واستغفروا الله","r":[2,199],"n":"أمر بالإفاضة من عرفات والاستغفار بعد الوقوف."},{"t":"اللهم مالك الملك","r":[3,26],"n":"ثناء على الله بالملك وإيتائه وسلبه والعزة والخير بيده."}]},{"id":"hifz","c":"yawm","t":"الحفظ والاستعاذة","d":"أدعية الاستعاذة وطلب الحفظ من شر المخلوقات ومن شر النفس، والتوكل على الله وحده.","ay":[{"t":"أعوذ بك من همزات الشياطين","r":[23,97,98],"n":"الاستعاذة بالله من وساوس الشياطين وحضورهم."},{"t":"حسبنا الله ونعم الوكيل","r":[3,173],"n":"قول المؤمنين حين خُوّفوا بالناس فزادهم إيماناً."},{"t":"حسبي الله لا إله إلا هو","r":[9,129],"n":"خاتمة التوبة: التوكل على رب العرش العظيم."}]}],"h":[{"id":"d-ibada","t":"الدعاء هو العبادة","x":"الدُّعَاءُ هُوَ الْعِبَادَةُ { قَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ","src":[["abudawud","1479"],["tirmidhi","2969"],["ibnmajah","3828"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"جعل النبي ﷺ الدعاء نفسه عبادة، فمن ترك الدعاء استكباراً فقد ترك عبادة، ومن دعا فقد عبد.","en":"The Prophet ﷺ said: \"Supplication is worship.\" Then he recited: \"Your Lord says: Call upon Me; I will respond to you.\"","ch":"adab"},{"id":"d-yastajab","t":"يستجاب لأحدكم ما لم يعجل","x":"يُسْتَجَابُ لأَحَدِكُمْ مَا لَمْ يَعْجَلْ يَقُولُ دَعَوْتُ فَلَمْ يُسْتَجَبْ لِي","src":[["bukhari","6340"],["muslim","2735"]],"gr":"صحيح: متفق عليه","dg":"","f":"من آداب الدعاء الصبر وإحسان الظن بالله، وألا يترك الداعي الدعاء لتأخر ظهور الإجابة.","en":"The Messenger of Allah ﷺ said: \"The supplication of any of you is answered as long as he does not grow hasty, saying: I supplicated but was not answered.\"","ch":"adab"},{"id":"d-mooqin","t":"ادعوا الله وأنتم موقنون بالإجابة","x":"ادْعُوا اللَّهَ وَأَنْتُمْ مُوقِنُونَ بِالإِجَابَةِ وَاعْلَمُوا أَنَّ اللَّهَ لاَ يَسْتَجِيبُ دُعَاءً مِنْ قَلْبٍ غَافِلٍ لاَهٍ","src":[["tirmidhi","3479"]],"gr":"","dg":"الألباني: حسن؛ أحمد شاكر: حسن؛ زبير علي زئي: ضعيف","f":"اليقين بالإجابة وحضور القلب شرطان من شروط الدعاء، ولا يُقبل دعاء من قلب غافل لاهٍ كما في الحديث.","en":"The Messenger of Allah ﷺ said: \"Supplicate Allah while you are certain of a response, and know that Allah does not answer the supplication of a heedless, distracted heart.\"","ch":"adab"},{"id":"d-nuzul","t":"ثلث الليل الآخر","x":"يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ يَقُولُ مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ","src":[["bukhari","1145"],["muslim","758"]],"gr":"صحيح: متفق عليه","dg":"","f":"من أوقات الإجابة المنصوص عليها: الثلث الأخير من الليل، حين ينادي الله عباده أن يسألوه ويستغفروه.","en":"The Messenger of Allah ﷺ said: \"Our Lord, Blessed and Exalted, descends every night to the lowest heaven when the last third of the night remains, and says: Who calls upon Me that I may respond? Who asks of Me that I may give him? Who seeks My forgiveness that I may forgive him?\"","ch":"adab"},{"id":"d-hasana","t":"ربنا آتنا في الدنيا حسنة","x":"اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","src":[["bukhari","4522"],["muslim","2690"]],"gr":"صحيح: متفق عليه","dg":"","f":"يذكر أنس ﵁ أنها كانت أكثر دعوة يدعو بها النبي ﷺ، فهي دعاء جامع يسير الحفظ.","en":"Anas ؓ said that the Prophet ﷺ used to say: \"Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.\"","ch":"jawami"},{"id":"d-islah","t":"اللهم أصلح لي ديني ودنياي وآخرتي","x":"اللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي وَأَصْلِحْ لِي دُنْيَاىَ الَّتِي فِيهَا مَعَاشِي وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ","src":[["muslim","2720"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يجمع إصلاح الدين والدنيا والآخرة، ويسأل أن تكون الحياة زيادة في الخير والموت راحة من الشر.","en":"The Messenger of Allah ﷺ used to say: \"O Allah, set right for me my religion, which is the safeguard of my affairs; set right for me my worldly life, in which is my livelihood; set right for me my Hereafter, to which is my return; make life an increase for me in every good, and make death a rest for me from every evil.\"","ch":"jawami"},{"id":"d-huda","t":"الهدى والتقى والعفاف والغنى","x":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","src":[["muslim","2721"],["tirmidhi","3489"],["ibnmajah","3832"]],"gr":"صحيح: رواه مسلم","dg":"","f":"أربعة مطالب جامعة: الهداية، والتقوى، والعفة عن الحرام وعن سؤال الناس، وغنى النفس.","en":"The Prophet ﷺ used to say: \"O Allah, I ask You for guidance, piety, chastity and self-sufficiency.\"","ch":"jawami"},{"id":"d-ghfr","t":"اللهم اغفر لي وارحمني واهدني وعافني وارزقني","x":"اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَعَافِنِي وَارْزُقْنِي","src":[["muslim","2697"]],"gr":"صحيح: رواه مسلم","dg":"","f":"خمس كلمات علّمها النبي ﷺ لمن دخل في الإسلام، فيها خيرا الدنيا والآخرة.","en":"The Prophet ﷺ taught a man who had newly embraced Islam to say: \"O Allah, forgive me, have mercy on me, guide me, grant me well-being and provide for me.\"","ch":"jawami"},{"id":"d-khayr","t":"اللهم إني أسألك من الخير كله","x":"اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ وَأَعُوذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَعُوذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا","src":[["ibnmajah","3846"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محمد فؤاد عبد الباقي: صحيح؛ زبير علي زئي: إسناده صحيح","f":"دعاء علّمه النبي ﷺ لعائشة ﵂ يستغرق الخير عاجله وآجله ما علمه الداعي وما لم يعلم.","en":"The Messenger of Allah ﷺ taught Aisha ؓ this supplication, asking for all good, immediate and delayed, what one knows of it and what one does not, and seeking refuge from all evil in the same way.","ch":"jawami"},{"id":"d-muqallib","t":"يا مقلب القلوب ثبّت قلبي على دينك","x":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ","src":[["tirmidhi","2140"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ زبير علي زئي: ضعيف","f":"كان النبي ﷺ يكثر منه، وعلّل ذلك بأن القلوب بين إصبعين من أصابع الرحمن يقلبها كيف يشاء.","en":"Anas ؓ said: The Messenger of Allah ﷺ often said: \"O Turner of hearts, make my heart firm upon Your religion.\" I said: Messenger of Allah, we believe in you and in what you brought; do you fear for us? He said: \"Yes, hearts are between two of the fingers of Allah; He turns them as He wills.\"","ch":"jawami"},{"id":"d-sayyid","t":"سيد الاستغفار","x":"سَيِّدُ الاِسْتِغْفَارِ أَنْ تَقُولَ اللَّهُمَّ أَنْتَ رَبِّي، لاَ إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَىَّ وَأَبُوءُ لَكَ بِذَنْبِي، فَاغْفِرْ لِي، فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ","src":[["bukhari","6306"],["bukhari","6323"],["tirmidhi","3393"]],"gr":"صحيح: رواه البخاري","dg":"","f":"سمّاه النبي ﷺ سيد الاستغفار لجمعه الإقرار بالربوبية والعبودية والعهد والذنب.","en":"The Prophet ﷺ said: \"The master of seeking forgiveness is to say: O Allah, You are my Lord, there is no god but You. You created me and I am Your servant, and I am upon Your covenant and promise as best I can. I seek refuge in You from the evil of what I have done. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for none forgives sins but You.\"","ch":"istighfar"},{"id":"d-khati","t":"اللهم اغفر لي خطيئتي وجهلي","x":"اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي هَزْلِي وَجِدِّي وَخَطَاىَ وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي","src":[["bukhari","6399"],["muslim","2719"]],"gr":"صحيح: متفق عليه","dg":"","f":"دعاء شامل لأصناف الذنوب: الخطأ والجهل والإسراف والجد والهزل والعمد.","en":"The Prophet ﷺ used to supplicate: \"O Allah, forgive me my mistake, my ignorance and my excess in my affairs, and what You know better than I. O Allah, forgive me what I did in seriousness and in jest, in error and on purpose; all of that is in me.\"","ch":"istighfar"},{"id":"d-tub","t":"رب اغفر لي وتب علي","x":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ","src":[["abudawud","1516"],["tirmidhi","3434"],["ibnmajah","3814"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: حسن صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: صحيح","f":"يروي ابن عمر ﵄ أنهم كانوا يعدّون للنبي ﷺ في المجلس الواحد مائة مرة، مع ما كان من مقامه ﷺ.","en":"Ibn Umar ؓ said: We used to count for the Messenger of Allah ﷺ in a single sitting a hundred times: \"My Lord, forgive me and accept my repentance; You are the Accepting of repentance, the Merciful.\"","ch":"istighfar"},{"id":"d-zalamtu","t":"اللهم إني ظلمت نفسي ظلماً كثيراً","x":"اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا ��َلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","src":[["bukhari","834"],["muslim","2705"]],"gr":"صحيح: متفق عليه","dg":"","f":"دعاء علّمه النبي ﷺ لأبي بكر ﵁ ليدعو به في صلاته.","en":"Abu Bakr ؓ asked the Messenger of Allah ﷺ to teach him a supplication to say in his prayer. He said: \"Say: O Allah, I have wronged myself greatly, and none forgives sins but You; so grant me forgiveness from You and have mercy on me. You are the Forgiving, the Merciful.\"","ch":"istighfar"},{"id":"d-humm","t":"اللهم إني أعوذ بك من الهم والحزن","x":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","src":[["bukhari","2893"],["tirmidhi","3484"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يقول أنس ﵁ إنه سمعه كثيراً حين ينزل، وهو دعاء جامع للاستعاذة من الهموم والعجز والبخل والدَّين.","en":"Anas ؓ said he often heard the Prophet ﷺ say: \"O Allah, I seek refuge in You from worry and grief, from incapacity and laziness, from miserliness and cowardice, from being overwhelmed by debt and from the domination of men.\"","ch":"karb"},{"id":"d-azim","t":"دعاء الكرب: لا إله إلا الله العظيم الحليم","x":"لاَ إِلَهَ إِلاَّ اللَّهُ الْعَظِيمُ الْحَلِيمُ لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لاَ إِلَهَ إِلاَّ اللَّهُ رَبُّ السَّمَوَاتِ وَرَبُّ الأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","src":[["muslim","2730"]],"gr":"صحيح: رواه مسلم","dg":"","f":"كان النبي ﷺ يقوله عند الكرب، وهو ثناء على الله يسبق الطلب.","en":"The Prophet of Allah ﷺ used to say at times of distress: \"There is no god but Allah, the Mighty, the Forbearing. There is no god but Allah, Lord of the mighty Throne. There is no god but Allah, Lord of the heavens, Lord of the earth and Lord of the noble Throne.\"","ch":"karb"},{"id":"d-rahma","t":"اللهم رحمتك أرجو","x":"دَعَوَاتُ الْمَكْرُوبِ اللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ وَأَصْلِحْ لِي شَأْنِي كُلَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ","src":[["abudawud","5090"]],"gr":"","dg":"الألباني: إسناده حسن؛ محيي الدين عبد الحميد: إسناده حسن؛ زبير علي زئي: ضعيف","f":"دعاء المكروب: التبرؤ من النفس وردّ الأمر كله إلى الله وطلب إصلاح الشأن.","en":"The Prophet ﷺ said: \"The supplications of the distressed: O Allah, Your mercy I hope for, so do not entrust me to myself even for the blink of an eye, and set right all my affairs; there is no god but You.\"","ch":"karb"},{"id":"d-nun","t":"دعوة ذي النون","x":"دَعْوَةُ ذِي النُّونِ إِذْ دَعَا وَهُوَ فِي بَطْنِ الْحُوتِ لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ . فَإِنَّهُ لَمْ يَدْعُ بِهَا رَجُلٌ مُسْلِمٌ فِي شَيْءٍ قَطُّ إِلاَّ اسْتَجَابَ اللَّهُ لَهُ","src":[["tirmidhi","3505"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ زبير علي زئي: إسناده صحيح","f":"بيّن النبي ﷺ أن من دعا بها في شيء قط استجاب الله له، وهي دعاء يونس ﵇.","en":"The Prophet ﷺ said: \"The supplication of Dhu al-Nun when he called out in the belly of the whale: There is no god but You, glory be to You, I was among the wrongdoers. No Muslim man supplicates with it for anything ever, except that Allah answers him.\"","ch":"karb"},{"id":"d-dayn","t":"اللهم اكفني بحلالك عن حرامك","x":"قُلِ اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","src":[["tirmidhi","3563"]],"gr":"","dg":"الألباني: حسن؛ أحمد شاكر: حسن؛ بشار عواد معروف: حسن؛ زبير علي زئي: حسن","f":"علّمه عليٌّ ﵁ لمكاتَب عجز عن كتابته، وفيه سؤال الكفاية بالحلال والغنى عن الخلق.","en":"Ali ؓ taught a contracted slave who could not pay his instalment: \"Say: O Allah, suffice me with what You made lawful over what You made unlawful, and enrich me by Your bounty over all besides You.\"","ch":"karb"},{"id":"d-musiba","t":"دعاء المصيبة","x":"مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللَّهُ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا","src":[["muslim","918"]],"gr":"صحيح: رواه مسلم","dg":"","f":"من أصابته مصيبة قال ما أمر الله به من الاسترجاع ثم سأل الأجر والخلف، وقد أخلف الله لأم سلمة ﵂ خيراً.","en":"The Messenger of Allah ﷺ said: \"Any Muslim struck by a calamity who says what Allah commanded: To Allah we belong and to Him we return; O Allah, reward me in my calamity and replace it for me with something better, Allah will replace it with something better for him.\"","ch":"karb"},{"id":"d-barik","t":"اللهم بارك لهم فيما رزقتهم","x":"اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","src":[["abudawud","3729"],["tirmidhi","3576"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: مسلم (2042)","f":"دعا النبي ﷺ لأهل بيت نزل عندهم بالبركة في الرزق والمغفرة والرحمة، وهو من آداب الضيافة.","en":"Abdullah ibn Busr ؓ said the Prophet ﷺ visited his father, who then took hold of the reins of the Prophet's mount and said: \"Supplicate Allah for us.\" So he said: \"O Allah, bless for them what You have provided them, forgive them and have mercy on them.\"","ch":"ahl"},{"id":"d-nafi","t":"اللهم إني أسألك علماً نافعاً","x":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلاً مُتَقَبَّلاً","src":[["ibnmajah","925"]],"gr":"","dg":"الألباني: صحيح؛ محمد فؤاد عبد الباقي: صحيح؛ زبير علي زئي: ضعيف","f":"كان النبي ﷺ يقوله إذا صلى الصبح حين يسلّم: علم نافع، ورزق طيب، وعمل متقبل.","en":"The Prophet ﷺ used to say, after the dawn prayer when he gave the salam: \"O Allah, I ask You for beneficial knowledge, good provision and accepted deeds.\"","ch":"ilm"},{"id":"d-yanfa","t":"أعوذ بك من علم لا ينفع","x":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلاَهَا اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لاَ يَنْفَعُ وَمِنْ قَلْبٍ لاَ يَخْشَعُ وَمِنْ نَفْسٍ لاَ تَشْبَعُ وَمِنْ دَعْوَةٍ لاَ يُسْتَجَابُ لَهَا","src":[["muslim","2722"]],"gr":"صحيح: رواه مسلم","dg":"","f":"الاستعاذة من أربع: علم لا ينفع، وقلب لا يخشع، ونفس لا تشبع، ودعوة لا يُستجاب لها.","en":"Zayd ibn Arqam ؓ said the Prophet ﷺ used to say: \"O Allah, I seek refuge in You from incapacity, laziness, cowardice, miserliness, old age and the punishment of the grave. O Allah, grant my soul its piety and purify it, You are the best to purify it, You are its Guardian and Master. O Allah, I seek refuge in You from knowledge that does not benefit, from a heart that does not humble itself, from a soul that is never satisfied and from a supplication that is not answered.\"","ch":"ilm"},{"id":"d-thabat","t":"اللهم إني أسألك الثبات في الأمر","x":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الأَمْرِ وَأَسْأَلُكَ عَزِيمَةَ الرُّشْدِ وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَحُسْنَ عِبَادَتِكَ وَأَسْأَلُكَ لِسَانًا صَادِقًا وَقَلْبًا سَلِيمًا وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ وَأَسْتَغْفِرُكَ مِمَّا تَعْلَمُ إِنَّكَ أَنْتَ عَلاَّمُ الْغُيُوبِ","src":[["tirmidhi","3407"]],"gr":"","dg":"الألباني: ضعيف؛ أحمد شاكر: ضعيف؛ زبير علي زئي: ضعيف","f":"يجمع الثبات والعزيمة على الرشد، وشكر النعمة وحسن العبادة، وقلباً سليماً ولساناً صادقاً.","en":"The Prophet ﷺ used to teach: \"O Allah, I ask You for steadfastness in the matter and resolve upon right guidance; I ask You to be grateful for Your favours and to worship You well; I ask You for a sound heart and a truthful tongue; I ask You for the good of what You know and seek Your refuge from the evil of what You know, and I ask Your forgiveness for what You know.\"","ch":"ilm"},{"id":"d-ainni","t":"رب أعنّي ولا تعن عليّ","x":"رَبِّ أَعِنِّي وَلاَ تُعِنْ عَلَىَّ وَانْصُرْنِي وَلاَ تَنْصُرْ عَلَىَّ وَامْكُرْ لِي وَلاَ تَمْكُرْ عَلَىَّ وَاهْدِنِي وَيَسِّرْ هُدَاىَ إِلَىَّ وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَىَّ اللَّهُمَّ اجْعَلْنِي لَكَ شَاكِرًا لَكَ ذَاكِرًا لَكَ رَاهِبًا لَكَ مِطْوَاعًا إِلَيْكَ مُخْبِتًا أَوْ مُنِيبًا رَبِّ تَقَبَّلْ تَوْبَتِي وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِي وَثَبِّتْ حُجَّتِي وَاهْدِ قَلْبِي وَسَدِّدْ لِسَانِي وَاسْلُلْ سَخِيمَةَ قَلْبِي","src":[["abudawud","1510"],["tirmidhi","3551"],["ibnmajah","3830"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"دعاء جامع للنصر والهداية والشكر والذكر والإنابة.","en":"Ibn Abbas ؓ said the Prophet ﷺ used to supplicate: \"My Lord, help me and do not help against me; support me and do not support others against me; plan for me and do not plan against me; guide me and make guidance easy for me; give me victory over whoever transgresses against me. My Lord, make me ever thankful to You, ever remembering You, ever fearing You, ever obedient to You, humble before You, always turning to You and returning to You. My Lord, accept my repentance, wash away my sin, answer my call, make my argument firm, guide my heart, make my tongue true and remove the rancour from my heart.\"","ch":"ilm"},{"id":"d-rushd","t":"اللهم ألهمني رشدي","x":"قُلِ اللَّهُمَّ أَلْهِمْنِي رُشْدِي وَأَعِذْنِي مِنْ شَرِّ نَفْسِي","src":[["tirmidhi","3483"]],"gr":"","dg":"الألباني: ضعيف؛ أحمد شاكر: ضعيف؛ بشار عواد معروف: حسن؛ زبير علي زئي: ضعيف","f":"علّمه النبي ﷺ لحصين ﵁ عند إسلامه: سؤال الرشد والاستعاذة من شر النفس.","en":"The Prophet ﷺ taught Husayn ؓ: \"Say: O Allah, inspire me with my right guidance and protect me from the evil of my own soul.\"","ch":"ilm"},{"id":"d-nawm","t":"دعاء النوم","x":"بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا \". وَإِذَا اسْتَيْقَظَ مِنْ مَنَامِهِ قَالَ \" الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ","src":[["bukhari","6324"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يُضجع النائم باسم الله ويجعل النوم موتاً صغيراً يستيقظ منه بالحمد.","en":"Hudhayfa ؓ said: When the Prophet ﷺ wished to sleep he said: \"In Your name, O Allah, I die and I live.\" And when he awoke from his sleep he said: \"Praise be to Allah who gave us life after He had caused us to die, and to Him is the resurrection.\"","ch":"yawm"},{"id":"d-faraash","t":"الحمد لله الذي أطعمنا وسقانا","x":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُئْوِيَ","src":[["muslim","2715"],["tirmidhi","3396"]],"gr":"صحيح: رواه مسلم","dg":"","f":"شكر عند الفراش على نعمة الطعام والكفاية والمأوى، وتذكير بمن لا كافي له ولا مأوى.","en":"Anas ؓ said that when the Messenger of Allah ﷺ went to his bed he said: \"Praise be to Allah who fed us, gave us drink, sufficed us and sheltered us; how many have none to suffice them and none to shelter them.\"","ch":"yawm"},{"id":"d-khuruj","t":"دعاء الخروج من البيت","x":"إِذَا خَرَجَ الرَّجُلُ مِنْ بَيْتِهِ فَقَالَ بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ \" . قَالَ \" يُقَالُ حِينَئِذٍ هُدِيتَ وَكُفِيتَ وَوُقِيتَ فَتَتَنَحَّى لَهُ الشَّيَاطِينُ","src":[["abudawud","5095"],["tirmidhi","3426"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: حسن","f":"من قاله قيل له: هُديت وكُفيت ووُقيت، وتنحّى عنه الشيطان.","en":"The Prophet ﷺ said: \"When a man leaves his house and says: In the name of Allah, I place my trust in Allah, there is no power and no might except with Allah, it is said to him: You are guided, defended and protected, and the devil steps aside from him.\"","ch":"yawm"},{"id":"d-libas","t":"دعاء لبس الثوب","x":"مَنْ لَبِسَ ثَوْبًا فَقَالَ الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","src":[["abudawud","4023"]],"gr":"","dg":"الألباني: حسن؛ محيي الدين عبد الحميد: حسن؛ زبير علي زئي: حسن","f":"شكر لله عند اللباس مع التبرؤ من الحول والقوة.","en":"The Prophet ﷺ said: \"Whoever puts on a garment and says: Praise be to Allah who clothed me with this and provided it for me without any power or might from me, his earlier sins are forgiven.\"","ch":"yawm"},{"id":"d-istikhara","t":"دعاء الاستخارة","x":"إِذَا هَمَّ أَحَدُكُمْ بِالأَمْرِ فَلْيَرْكَعْ رَكْعَتَيْنِ مِنْ غَيْرِ الْفَرِيضَةِ ثُمَّ لِيَقُلِ اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ وَتَعْلَمُ وَلاَ أَعْلَمُ وَأَنْتَ عَلاَّمُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي ـ أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ ـ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِي بِهِ ـ قَالَ ـ وَيُسَمِّي حَاجَتَهُ","src":[["bukhari","1166"],["abudawud","1538"],["tirmidhi","480"],["ibnmajah","1383"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يقول جابر ﵁ إن النبي ﷺ كان يعلّمهم الاستخارة في الأمور كلها كما يعلّمهم السورة من القرآن.","en":"Jabir ؓ said the Messenger of Allah ﷺ used to teach us the istikhara in all matters, as he taught us a surah of the Quran. He said: \"When any of you is concerned about a matter, let him pray two units other than the obligatory prayer, then say: O Allah, I seek Your guidance by Your knowledge and Your power by Your might, and I ask You of Your immense bounty; for You are able and I am not, You know and I do not, and You are the Knower of the unseen. O Allah, if You know that this matter is good for me in my religion, my livelihood and the outcome of my affairs, then decree it for me, ease it for me and bless it for me; and if You know that it is bad for me in my religion, my livelihood and the outcome of my affairs, then turn it away from me and turn me away from it, decree the good for me wherever it is and make me content with it. And let him name his need.\"","ch":"yawm"},{"id":"d-khala","t":"دعاء دخول الخلاء","x":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","src":[["bukhari","142"],["muslim","375"]],"gr":"صحيح: متفق عليه","dg":"","f":"يستعيذ الداخل من الخلاء بالله من الشياطين ذكورهم وإناثهم.","en":"Anas ؓ said that when the Prophet ﷺ entered the toilet he said: \"O Allah, I seek refuge in You from the male and female devils.\"","ch":"salat"},{"id":"d-ghufran","t":"غفرانك","x":"غُفْرَانَكَ","src":[["abudawud","30"],["tirmidhi","7"],["ibnmajah","300"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"كان النبي ﷺ يقولها إذا خرج من الخلاء، سؤالاً للمغفرة عند الفراغ.","en":"Aisha ؓ said that when the Prophet ﷺ came out of the toilet he said: \"Your forgiveness.\"","ch":"salat"},{"id":"d-masjid","t":"دعاء دخول المسجد والخروج منه","x":"إِذَا دَخَلَ أَحَدُكُمُ الْمَسْجِدَ فَلْيَقُلِ اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ . وَإِذَا خَرَجَ فَلْيَقُلِ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","src":[["muslim","713"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يسأل الداخل رحمة الله وفتح أبوابها، ويسأل الخارج فضله.","en":"The Messenger of Allah ﷺ said: \"When any of you enters the mosque let him say: O Allah, open for me the doors of Your mercy. And when he leaves let him say: O Allah, I ask You of Your bounty.\"","ch":"salat"},{"id":"d-adhan","t":"الدعاء بعد الأذان","x":"مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلاَةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ","src":[["bukhari","614"],["abudawud","529"]],"gr":"صحيح: رواه البخاري","dg":"","f":"من قاله حلّت له شفاعة النبي ﷺ يوم القيامة، وفيه سؤال الوسيلة والمقام المحمود له ﷺ.","en":"The Messenger of Allah ﷺ said: \"Whoever says, when he hears the call: O Allah, Lord of this perfect call and of the prayer to be established, grant Muhammad the intercession and the favour, and raise him to the praised station You have promised him, my intercession will be due for him on the Day of Resurrection.\"","ch":"salat"},{"id":"d-qabr","t":"الاستعاذة قبل السلام من الصلاة","x":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ","src":[["bukhari","832"],["muslim","589"]],"gr":"صحيح: متفق عليه","dg":"","f":"كان النبي ﷺ يدعو به في الصلاة: الاستعاذة من عذاب القبر وفتنة الدجال وفتنة المحيا والممات والمأثم والمغرم.","en":"Aisha ؓ said the Prophet ﷺ used to supplicate in prayer: \"O Allah, I seek refuge in You from the punishment of the grave, from the trial of the False Messiah, and from the trials of life and death. O Allah, I seek refuge in You from sin and debt.\"","ch":"salat"},{"id":"d-dhikrak","t":"اللهم أعني على ذكرك وشكرك","x":"لاَ تَدَعَنَّ فِي دُبُرِ كُلِّ صَلاَةٍ تَقُولُ اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","src":[["abudawud","1522"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"أوصى بها النبي ﷺ معاذ بن جبل ﵁ بعد أن قال له: والله إني لأحبك.","en":"The Prophet ﷺ said to Mu'adh ؓ: \"I advise you, Mu'adh: never fail to say after every prayer: O Allah, help me to remember You, to thank You and to worship You well.\"","ch":"salat"},{"id":"d-safar","t":"دعاء السفر","x":"إِذَا اسْتَوَى عَلَى بَعِيرِهِ خَارِجًا إِلَى سَفَرٍ كَبَّرَ ثَلاَثًا ثُمَّ قَالَ \" سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الأَهْلِ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالأَهْلِ\"","src":[["muslim","1342"],["abudawud","2599"],["tirmidhi","3446"]],"gr":"صحيح: رواه مسلم","dg":"","f":"كان النبي ﷺ يكبّر ثلاثاً ثم يقول دعاء الركوب، ثم يسأل البر والتقوى وهوان السفر.","en":"Ibn Umar ؓ said that when the Messenger of Allah ﷺ settled on his camel to set out on a journey he said \"Allahu akbar\" three times and then: \"Glory be to Him who subjected this to us, and we could not have subdued it; and to our Lord we shall return. O Allah, we ask You on this journey of ours for righteousness, piety and deeds that please You. O Allah, make this journey easy for us and fold up its distance for us. O Allah, You are the Companion on the journey and the Guardian of the family. O Allah, I seek refuge in You from the hardship of travel, from a sorrowful sight, and from a bad return in wealth and family.\"","ch":"safar"},{"id":"d-manzil","t":"دعاء النزول في المنزل","x":"مَنْ نَزَلَ مَنْزِلاً ثُمَّ قَالَ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ . لَمْ يَضُرُّهُ شَىْءٌ حَتَّى يَرْتَحِلَ مِنْ مَنْزِلِهِ ذَلِكَ","src":[["muslim","2708"],["tirmidhi","3437"]],"gr":"صحيح: رواه مسلم","dg":"","f":"من قالها لم يضره شيء حتى يرتحل من منزله ذلك.","en":"Khawla bint Hakim ؓ said she heard the Messenger of Allah ﷺ say: \"Whoever stops at a stopping place and then says: I seek refuge in the perfect words of Allah from the evil of what He created, nothing will harm him until he departs from that place.\"","ch":"safar"},{"id":"d-shifa","t":"اللهم رب الناس أذهب الباس","x":"أَذْهِبِ الْبَاسَ رَبَّ النَّاسِ، اشْفِ وَأَنْتَ الشَّافِي لاَ شِفَاءَ إِلاَّ شِفَاؤُكَ، شِفَاءً لاَ يُغَادِرُ سَقَمًا","src":[["bukhari","5675"],["muslim","2191"]],"gr":"صحيح: متفق عليه","dg":"","f":"كان النبي ﷺ يقوله للمريض، وفيه حصر الشفاء بالله وسؤال شفاء لا يترك سقماً.","en":"Aisha ؓ said that when the Prophet ﷺ visited a sick person he would say: \"Remove the affliction, Lord of the people; heal, for You are the Healer; there is no healing but Your healing, a healing that leaves no illness.\"","ch":"maradh"},{"id":"d-afiya","t":"اللهم عافني في بدني","x":"اللَّهُمَّ عَافِنِي فِي بَدَنِي اللَّهُمَّ عَافِنِي فِي سَمْعِي اللَّهُمَّ عَافِنِي فِي بَصَرِي لاَ إِلَهَ إِلاَّ أَنْتَ","src":[["abudawud","5090"]],"gr":"","dg":"الألباني: إسناده حسن؛ محيي الدين عبد الحميد: إسناده حسن؛ زبير علي زئي: ضعيف","f":"أخبر أبو بكرة ﵁ ابنه أنه سمع النبي ﷺ بها فأحب أن يستنّ بسنته: العافية في البدن والسمع والبصر.","en":"Abu Bakra ؓ said: I heard the Prophet ﷺ supplicate with these words, so I love to follow his Sunna: \"O Allah, grant me well-being in my body; O Allah, grant me well-being in my hearing; O Allah, grant me well-being in my sight; there is no god but You.\"","ch":"maradh"},{"id":"d-istisqa","t":"دعاء الاستسقاء","x":"اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعاً نَافِعًا غَيْرَ ضَارٍّ عَاجِلاً غَيْرَ آجِلٍ","src":[["abudawud","1169"],["ibnmajah","1270"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: حسن؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده حسن","f":"يسأل المطر النافع غير الضار، الذي يأتي في أوانه.","en":"The Messenger of Allah ﷺ supplicated: \"O Allah, give us rain, helpful, wholesome, fertile, beneficial and not harmful, quickly and not delayed.\"","ch":"rizq"},{"id":"d-thimar","t":"اللهم بارك لنا في ثمارنا","x":"اللَّهُمَّ بَارِكْ لَنَا فِي ثِمَارِنَا وَبَارِكْ لَنَا فِي مَدِينَتِنَا وَبَارِكْ لَنَا فِي صَاعِنَا وَمُدِّنَا","src":[["tirmidhi","3454"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ بشار عواد معروف: حسن صحيح؛ زبير علي زئي: صحيح، متفق عليه","f":"كان الناس يأتون بأول الثمر إلى النبي ﷺ فيدعو بالبركة ثم يعطيه أصغر وليد حاضر.","en":"Abu Hurayra ؓ said that when people brought the first of the fruit to the Messenger of Allah ﷺ he said: \"O Allah, bless us in our fruit, bless us in our city, bless us in our sa' and in our mudd.\"","ch":"rizq"},{"id":"d-afuw","t":"اللهم إنك عفو تحب العفو","x":"تَقُولِينَ اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","src":[["ibnmajah","3850"],["tirmidhi","3513"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: حسن صحيح؛ محمد فؤاد عبد الباقي: صحيح؛ زبير علي زئي: ضعيف","f":"علّمه النبي ﷺ عائشة ﵂ حين سألته: إن وافقتُ ليلة القدر ما أدعو؟","en":"Aisha ؓ asked: Messenger of Allah, if I find Laylat al-Qadr what should I say? He said: \"Say: O Allah, You are Pardoning and love pardon, so pardon me.\"","ch":"mawsim"},{"id":"d-arafa","t":"خير الدعاء دعاء يوم عرفة","x":"خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبِيُّونَ مِنْ قَبْلِي لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","src":[["tirmidhi","3585"]],"gr":"","dg":"الألباني: حسن؛ أحمد شاكر: حسن؛ زبير علي زئي: ضعيف","f":"يبيّن أفضلية دعاء يوم عرفة وأن أفضل ما قاله النبي ﷺ والنبيون قبله كلمة التوحيد وذكرها.","en":"The Prophet ﷺ said: \"The best supplication is the supplication of the Day of Arafah, and the best of what I and the prophets before me have said is: There is no god but Allah alone with no partner; His is the dominion and His is the praise, and He has power over all things.\"","ch":"mawsim"},{"id":"d-bismillah","t":"بسم الله الذي لا يضر مع اسمه شيء","x":"مَنْ قَالَ بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَىْءٌ فِي الأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ ثَلاَثَ مَرَّاتٍ لَمْ تُصِبْهُ فَجْأَةُ بَلاَءٍ حَتَّى يُصْبِحَ وَمَنْ قَالَهَا حِينَ يُصْبِحُ ثَلاَثَ مَرَّاتٍ لَمْ تُصِبْهُ فَجْأَةُ بَلاَءٍ حَتَّى يُمْسِيَ","src":[["abudawud","5088"],["tirmidhi","3388"]],"gr":"","dg":"الألباني: صحيح؛ زبير علي زئي: صحيح","f":"جاء في الحديث أن من قالها ثلاثاً صباحاً لم تصبه فجأة بلاء حتى يمسي، ومن قالها ثلاثاً مساءً لم تصبه فجأة بلاء حتى يصبح.","en":"Uthman ؓ reported that the Messenger of Allah ﷺ said: \"Whoever says: In the name of Allah, with whose name nothing on earth or in heaven can cause harm, and He is the All-Hearing, the All-Knowing, three times, no sudden affliction will befall him until morning; and whoever says it three times in the morning, no sudden affliction will befall him until evening.\"","ch":"hifz"},{"id":"d-shar","t":"أعوذ من شر ما عملت ومن شر ما لم أعمل","x":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ","src":[["muslim","2716"],["abudawud","1550"],["ibnmajah","3839"]],"gr":"صحيح: رواه مسلم","dg":"","f":"سألت عائشة ﵂ عما كان النبي ﷺ يدعو به، فذكرت هذا الدعاء: الاستعاذة من شر العمل الماضي ومن شر ما لم يُعمل.","en":"Aisha ؓ was asked what the Messenger of Allah ﷺ used to supplicate with; she said he used to say: \"O Allah, I seek refuge in You from the evil of what I have done and from the evil of what I have not done.\"","ch":"hifz"}],"q":[{"ch":"adab","w":"السعدي","bk":"saadi","s":2,"ay":186,"x":"والدعاء نوعان: دعاء عبادة، ودعاء مسألة","n":"أن الدعاء يشمل دعاء العبادة ودعاء المسألة.","en":"\"Supplication is of two kinds: supplication of worship and supplication of request.\""},{"ch":"adab","w":"ابن كثير","bk":"ibnkathir","s":40,"ay":60,"x":"هَذَا مِنْ فَضْلِهِ، تَبَارَكَ وَتَعَالَى، وَكَرَمِهِ أَنَّهُ نَدَبَ عِبَادَهُ إِلَى دُعَائِهِ، وَتَكَفَّلَ لَهُمْ بِالْإِجَابَةِ، كَمَا كَانَ سُفْيَانُ الثَّوْرِيُّ يَقُولُ: يَا مَنْ أحبُّ عِبَادِهِ إِلَيْهِ مَنْ سَأَلَهُ فَأَكْثَرَ سُؤَالَهُ، وَيَا مَنْ أَبْغَضُ عِبَادِهِ إِلَيْهِ مَنْ لَمْ يَسْأَلْهُ، وَلَيْسَ كَذَلِكَ غَيْرُكَ يَا رَبِّ","n":"كرم الله في أن ندب عباده إلى دعائه وتكفل لهم بالإجابة.","en":"\"This is of His bounty and generosity: He urged His servants to supplicate Him and guaranteed them the response.\""},{"ch":"ahl","w":"السعدي","bk":"saadi","s":17,"ay":24,"x":"{وقل ربِّ ارحَمۡهما}؛ أي: ادعُ لهما بالرحمة أحياءً وأمواتاً؛ جزاءً على تربيتهما إيَّاك صغيراً. وفُهِمَ من هذا أنَّه كلَّما ازدادت التربيةُ؛ ازداد الحقُّ","n":"أن الدعاء للوالدين من حق التربية، وأن الحق يزيد بزيادة التربية.","en":"\"And say: 'My Lord, have mercy on them': that is, supplicate for them with mercy, alive and dead, as recompense for raising you as a child. It is understood from this that the more the upbringing, the greater the right.\""},{"ch":"ilm","w":"السعدي","bk":"saadi","s":20,"ay":25,"x":"{ربِّ اشرحۡ لي صدري}؛ أي: وسِّعه وافسحْه لأتحمَّل الأذى القوليَّ والفعليَّ، ولا يتكدَّر قلبي بذلك، ولا يضيق صدري؛ فإنَّ الصدر إذا ضاق؛ لم يصلح صاحبُه لهداية الخلق ودعوتهم","n":"لماذا سأل موسى ﵇ انشراح الصدر أول ما سأل.","en":"\"My Lord, expand my chest\": that is, widen and open it so that I may bear verbal and physical harm, my heart not be troubled by it and my chest not be constricted; for when the chest is constricted, its owner is unfit to guide and call people.\""},{"ch":"hifz","w":"السعدي","bk":"saadi","s":9,"ay":129,"x":"وقل:{حسبيَ الله}؛ أي: الله كافِيَّ في جميع ما أهمني. {لا إله إلَّا هو}؛ أي: لا معبود بحقٍّ سواه. {عليه توكلتُ}؛ أي: اعتمدت ووثقت به في جلب ما ينفع ودفع ما يضرُّ. {وهو ربُّ العرش العظيم","n":"معنى «حسبي الله» والتوكل عليه.","en":"\"Allah is sufficient for me\": that is, Allah suffices me in everything that concerns me; \"there is no god but He\": no one is truly worshipped but Him; \"in Him I have put my trust\": I relied and placed my confidence in Him to bring benefit and avert harm; \"and He is the Lord of the mighty Throne\"."}],"ay":{"5":"ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ","6":"صِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ","133":"وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","134":"رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَيۡنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةٗ مُّسۡلِمَةٗ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَيۡنَآۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","192":"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ","205":"ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","207":"وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ","256":"وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","291":"ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيۡنَ أَحَدٖ مِّن رُّسُلِهِۦۚ وَقَالُواْ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَيۡكَ ٱلۡمَصِيرُ","292":"لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","300":"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ","308":"ٱلَّذِينَ يَقُولُونَ رَبَّنَآ إِنَّنَآ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ","318":"قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","330":"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ","465":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ","485":"رَّبَّنَآ إِنَّنَا سَمِعۡنَا مُنَادِيٗا يُنَادِي لِلۡإِيمَٰنِ أَنۡ ءَامِنُواْ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ","486":"رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا يَوۡمَ ٱلۡقِيَٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِيعَادَ","782":"قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ ٱللَّهُمَّ رَبَّنَآ أَنزِلۡ عَلَيۡنَا مَآئِدَةٗ مِّنَ ٱلسَّمَآءِ تَكُونُ لَنَا عِيدٗا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَايَةٗ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَيۡرُ ٱلرَّٰزِقِينَ","976":"قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ","1008":"ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ","1009":"وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ","1079":"وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ","1133":"وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ","1363":"فَإِن تَوَلَّوۡاْ فَقُلۡ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ","1513":"۞ وَقَالَ ٱرۡكَبُواْ فِيهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَآۚ إِنَّ رَبِّي لَغَفُورٞ رَّحِيمٞ","1789":"رَبِّ ٱجۡعَلۡنِي مُقِيمَ ٱلصَّلَوٰةِ وَمِن ذُرِّيَّتِيۚ رَبَّنَا وَتَقَبَّلۡ دُعَآءِ","1790":"رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ","2052":"وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا","2108":"وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا","2149":"إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا","2372":"قَالَ رَبِّ ٱشۡرَحۡ لِي صَدۡرِي","2373":"وَيَسِّرۡ لِيٓ أَمۡرِي","2374":"وَٱحۡلُلۡ عُقۡدَةٗ مِّن لِّسَانِي","2375":"يَفۡقَهُواْ قَوۡلِي","2461":"فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا","2565":"۞ وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ","2566":"فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ","2569":"وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ","2701":"وَقُل رَّبِّ أَنزِلۡنِي مُنزَلٗا مُّبَارَكٗا وَأَنتَ خَيۡرُ ٱلۡمُنزِلِينَ","2769":"وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ","2770":"وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ","2790":"وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَيۡرُ ٱلرَّٰحِمِينَ","2928":"وَٱلَّذِينَ يَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَٰجِنَا وَذُرِّيَّٰتِنَا قُرَّةَ أَعۡيُنٖ وَٱجۡعَلۡنَا لِلۡمُتَّقِينَ إِمَامًا","3009":"ٱلَّذِي خَلَقَنِي فَهُوَ يَهۡدِينِ","3010":"وَٱلَّذِي هُوَ يُطۡعِمُنِي وَيَسۡقِينِ","3011":"وَإِذَا مَرِضۡتُ فَهُوَ يَشۡفِينِ","3012":"وَٱلَّذِي يُمِيتُنِي ثُمَّ يُحۡيِينِ","3013":"وَٱلَّذِيٓ أَطۡمَعُ أَن يَغۡفِرَ لِي خَطِيٓـَٔتِي يَوۡمَ ٱلدِّينِ","3275":"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰٓ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّي لِمَآ أَنزَلۡتَ إِلَيَّ مِنۡ خَيۡرٖ فَقِيرٞ","4192":"وَقَالَ رَبُّكُمُ ٱدۡعُونِيٓ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِينَ يَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِي سَيَدۡخُلُونَ جَهَنَّمَ دَاخِرِينَ","4337":"لِتَسۡتَوُۥاْ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُواْ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَيۡتُمۡ عَلَيۡهِ وَتَقُولُواْ سُبۡحَٰنَ ٱلَّذِي سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِينَ","4338":"وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ","4524":"وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ","5236":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ تُوبُوٓاْ إِلَى ٱللَّهِ تَوۡبَةٗ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن يُكَفِّرَ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيُدۡخِلَكُمۡ جَنَّٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ يَوۡمَ لَا يُخۡزِي ٱللَّهُ ٱلنَّبِيَّ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥۖ نُورُهُمۡ يَسۡعَىٰ بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۡ يَقُولُونَ رَبَّنَآ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَآۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","5446":"رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ وَلَا تَزِدِ ٱلظَّٰلِمِينَ إِلَّا تَبَارَۢا"},"nay":55},"ibadat":{"cats":[["asl","الأصل والمنزلة"],["siyam","الصيام"],["zakat","الزكاة"]],"ch":[{"id":"arkan","c":"asl","t":"الحج والصيام والزكاة من أركان الإسلام","d":"بُني الإسلام على خمسة، ومنها الحج والصيام والزكاة؛ وهي عبادات لكل منها شروط وأركان ومفسدات، وأحكامها الأساسية ثابتة بالنص.","ay":[{"t":"حج البيت على الناس","r":[3,97],"n":"فرضٌ على من استطاع إليه سبيلاً."},{"t":"كتب عليكم الصيام","r":[2,183],"n":"فُرض الصيام على الأمم قبلنا، وغايته التقوى."},{"t":"خذ من أموالهم صدقة","r":[9,103],"n":"أمر بأخذ الزكاة تطهيراً وتزكية، مع الدعاء لأصحابها."}]},{"id":"siyam","c":"siyam","t":"الصيام: فرضه وشروطه ورؤية الهلال والنية","d":"صيام رمضان فرض على كل مسلم بالغ عاقل مقيم قادر، من طلوع الفجر إلى غروب الشمس.","ay":[{"t":"كتب عليكم الصيام","r":[2,183],"n":"فرض الصيام وحكمته: لعلكم تتقون."},{"t":"فمن شهد منكم الشهر فليصمه","r":[2,185],"n":"الشهر الذي أنزل فيه القرآن، ورخصة المريض والمسافر، واليسر."},{"t":"وكلوا واشربوا حتى يتبين لكم الخيط الأبيض","r":[2,187],"n":"حد الصيام: من تبين الفجر إلى الليل، وأحكام الاعتكاف."}],"st":[{"t":"شروط وجوبه","x":"الإسلام والبلوغ والعقل والقدرة والإقامة؛ ويُؤمر الصبي المميز به ليتعوّد، والحائض والنفساء لا تصومان وتقضيان."},{"t":"ثبوت الشهر","x":"بالرؤية الشرعية للهلال أو بإكمال شعبان ثلاثين يوماً إذا غُمّ الهلال، ولا يُقدَّم رمضان بصوم يوم أو يومين إلا لمن كانت له عادة."},{"t":"النية","x":"يجب تبييتها من الليل لكل يوم من رمضان عند الجمهور، وهي عمل القلب ولا يُشترط التلفظ بها."},{"t":"وقت الصيام","x":"من طلوع الفجر الصادق إلى غروب الشمس، يمسك فيه عن المفطرات."},{"t":"السحور والفطر","x":"السحور سنة وفيه بركة، ويستحب تأخيره، وتعجيل الفطر سنة، ويفطر على رطب أو تمر أو ماء."}],"kh":[{"t":"النية في الصيام الواجب","n":"ورد الحديث: «من لم يجمع الصيام قبل الفجر فلا صيام له».","p":[["الجمهور (المالكية والشافعية والحنابلة)","تُبيَّت من الليل، ولا تصح بعد طلوع الفجر في الفرض، ويكفي عند المالكية نية واحدة في أول الشهر."],["الحنفية","تصح نية رمضان والنذر المعين قبل الزوال."]]},{"t":"اختلاف المطالع في رؤية الهلال","n":"هل يلزم أهل بلد صيام من رؤية بلد آخر؟","p":[["الحنفية والمالكية والحنابلة","رؤية بلد تلزم سائر البلاد."],["الشافعية","يُعتبر اختلاف المطالع، فلكل بلد رؤيتهم."]]}]},{"id":"mufattirat","c":"siyam","t":"مفطرات الصيام وأعذاره وكفارته","d":"ما يفسد الصوم، وما لا يفسده، ومتى يجوز الفطر، وما يلزم من أفطر عمداً بالجماع في نهار رمضان.","ay":[{"t":"ثم أتموا الصيام إلى الليل","r":[2,187],"n":"حد الصيام وبيان أن الأكل والشرب مباحان بالليل إلى تبين الفجر."},{"t":"فمن كان منكم مريضاً أو على سفر","r":[2,184],"n":"رخصة المريض والمسافر مع القضاء، والفدية على من لا يطيقه."}],"st":[{"t":"ما يفطر","x":"الأكل والشرب عمداً، والجماع، والقيء عمداً، وخروج دم الحيض والنفاس، وما في معنى الأكل والشرب مما يصل إلى الجوف."},{"t":"ما لا يفطر","x":"الأكل والشرب ناسياً أو مخطئاً، والقيء الذي يغلب الإنسان، وغبار الطريق والذباب ونحوه مما لا يمكن التحرز منه، والاغتسال والسواك."},{"t":"أصحاب الأعذار","x":"المريض الذي يشق عليه الصوم والمسافر يفطران ويقضيان، والكبير العاجز والمريض الذي لا يُرجى برؤه يطعمان عن كل يوم مسكيناً، والحائض والنفساء تفطران وتقضيان."},{"t":"كفارة الجماع في نهار رمضان","x":"من جامع عامداً في نهار رمضان وهو صائم فعليه القضاء والكفارة المرتبة: عتق رقبة، فإن لم يجد فصيام شهرين متتابعين، فإن لم يستطع فإطعام ستين مسكيناً."}],"kh":[{"t":"الأكل والشرب نسياناً","n":"ثبت الحديث بأن من نسي فأكل أو شرب فليتم صومه.","p":[["الجمهور (الحنفية والشافعية والحنابلة)","لا يفسد الصوم."],["المالكية","يفسد وعليه القضاء بلا كفارة."]]},{"t":"كفارة الأكل والشرب عمداً","n":"اتفقوا على القضاء، واختلفوا في الكفارة.","p":[["الحنفية والمالكية","تجب الكفارة كما في الجماع."],["الشافعية والحنابلة","لا كفارة إلا في الجماع."]]},{"t":"الحجامة للصائم","n":"ورد في الباب حديثان: «أفطر الحاجم والمحجوم» واحتجامه ﷺ وهو صائم.","p":[["الحنابلة","تفطر الحاجم والمحجوم."],["الجمهور (الحنفية والمالكية والشافعية)","لا تفطر."]]},{"t":"الحامل والمرضع","n":"اتفقوا على جواز الفطر لهما مع القضاء إن خافتا على أنفسهما، واختلفوا في الفدية.","p":[["الحنفية","القضاء بلا فدية."],["الشافعية والحنابلة","القضاء مع الفدية إن خافتا على الولد فقط."],["المالكية","الحامل تقضي بلا فدية، والمرضع تقضي وتفدي."]]},{"t":"مقدار الفدية","n":"لمن لا يقدر على الصيام ولا القضاء.","p":[["الجمهور","مُدّ من طعام لكل يوم."],["الحنفية","نصف صاع من بُرّ (نحو وجبة كاملة) لكل يوم."]]}]},{"id":"adab-siyam","c":"siyam","t":"فضل الصيام وليلة القدر والصيام المسنون","d":"فضائل الصيام وآدابه: حفظ اللسان وترك الزور، والعشر الأواخر وليلة القدر، والصيام المسنون في الأشهر والأيام الفاضلة.","ay":[{"t":"إنا أنزلناه في ليلة القدر","r":[97,1,5],"n":"سورة القدر: ليلة القدر خير من ألف شهر."}],"st":[{"t":"آداب الصائم","x":"الإمساك عن الكلام الفاحش والصخب والجهل، فإذا شاتمه أحد قال: إني صائم، مع الإكثار من القرآن والصدقة والذكر."},{"t":"الاعتكاف والعشر الأواخر","x":"كان النبي ﷺ يجتهد في العشر الأواخر أكثر من غيرها، ويلتمس ليلة القدر في الوتر منها."},{"t":"صيام التطوع","x":"ستة أيام من شوال، ويوم عرفة لغير الحاج، وعاشوراء، وثلاثة أيام من كل شهر، والاثنين والخميس، وكان أبو هريرة ﵁ أوصاه النبي ﷺ بثلاثة أيام من كل شهر."}],"kh":[{"t":"صيام ست من شوال","n":"ثبت الحديث بفضلها.","p":[["الشافعية والحنابلة","سنة مستحبة."],["الحنفية","مباحة ولا بأس بها (وبعض متأخري الحنفية على استحبابها)."],["المالكية","تُكره خشية أن يُظن وجوبها."]]}]},{"id":"zakat","c":"zakat","t":"الزكاة: وجوبها وشروطها وأنواع الأموال","d":"الزكاة حق الفقراء في أموال الأغنياء، تطهّر المال وصاحبه، وتجب إذا بلغ المال النصاب وحال عليه الحول.","ay":[{"t":"خذ من أموالهم صدقة تطهرهم","r":[9,103],"n":"الزكاة تطهير وتزكية."},{"t":"أنفقوا من طيبات ما كسبتم","r":[2,267],"n":"الأمر بالإنفاق من الطيب مما كسب الناس ومما أخرج الله من الأرض."},{"t":"الذين يكنزون الذهب والفضة","r":[9,34,35],"n":"وعيد من يكنز الذهب والفضة ولا ينفقهما في سبيل الله."}],"st":[{"t":"شروط وجوبها","x":"الإسلام، والحرية، وملك النصاب ملكاً تاماً، وأن يزيد على حاجاته الأصلية، ومضي حول كامل (إلا الزروع والثمار والمعدن)."},{"t":"الذهب والفضة والنقود","x":"نصاب الذهب عشرون مثقالاً (نحو ٨٥ غراماً)، ونصاب الفضة مئتا درهم (نحو ٥٩٥ غراماً)، والواجب ربع العشر (٢٫٥٪). وفي معيار النقود الورقية خلاف بين المعاصرين، والأحوط أن يسأل المسلم دار الإفتاء في بلده."},{"t":"عروض التجارة","x":"تُقوَّم ما أُعدّ للبيع والشراء بسعر السوق عند تمام الحول، ويُخرج ربع العشر إن بلغت النصاب."},{"t":"الزروع والثمار","x":"نصابها خمسة أوسق (نحو ٦٥٣ كغ)، والواجب العشر فيما سُقي بلا مؤونة، ونصف العشر فيما سُقي بمؤونة، ويُخرج عند الحصاد."},{"t":"الأنعام السائمة","x":"الإبل والبقر والغنم التي ترعى أكثر العام فيها زكاة بنصب مفصلة: أول نصاب الإبل خمس، والغنم أربعون، وتفصيله في حديث الصدقات المنقول أدناه."}],"kh":[{"t":"زكاة الحلي المباح للنساء","n":"هل يزكى حلي المرأة المعدّ للاستعمال؟","p":[["الحنفية","تجب فيه الزكاة."],["الجمهور (المالكية والشافعية والحنابلة)","لا زكاة فيه إذا كان مباحاً معداً للاستعمال أو العارية."]]},{"t":"نصاب الزروع والثمار","n":"ورد: «ليس فيما دون خمسة أوسق صدقة»، و«فيما سقت السماء العشر».","p":[["الجمهور (المالكية والشافعية والحنابلة)","يُشترط بلوغ خمسة أوسق."],["الحنفية","تجب في القليل والكثير مما تُنبته الأرض بلا نصاب."]]}]},{"id":"masarif","c":"zakat","t":"مصارف الزكاة وزكاة الفطر","d":"حصر الله مصارف الزكاة في ثمانية أصناف، ولا تصرف في غيرها؛ وزكاة الفطر طهرة للصائم وطعمة للمساكين.","ay":[{"t":"إنما الصدقات للفقراء والمساكين","r":[9,60],"n":"الأصناف الثمانية: الفقراء والمساكين والعاملون عليها والمؤلفة قلوبهم وفي الرقاب والغارمون وفي سبيل الله وابن السبيل."}],"st":[{"t":"الأصناف الثمانية","x":"الفقراء، والمساكين، والعاملون عليها، والمؤلفة قلوبهم، وفي الرقاب، والغارمون، وفي سبيل الله، وابن السبيل؛ ولا تُجزئ لغيرهم."},{"t":"من لا تُدفع إليهم","x":"الغني، والقوي المكتسب، وأصول المزكّي وفروعه الذين تلزمه نفقتهم، وآل النبي ﷺ."},{"t":"زكاة الفطر","x":"فرضها النبي ﷺ صاعاً من تمر أو شعير أو طعام على كل مسلم: الصغير والكبير، الذكر والأنثى، الحر والعبد. وهي طهرة للصائم من اللغو والرفث وطعمة للمساكين؛ ووقت وجوبها غروب شمس آخر يوم من رمضان عند الجمهور (وعند الحنفية بطلوع فجر العيد)، وتُؤدّى قبل صلاة العيد، فمن أداها قبل الصلاة فهي زكاة مقبولة."},{"t":"مقدار الصاع","x":"يقدّره الفقهاء بنحو أربعة أمداد، ويقارب ثلاثة كيلوغرامات من قوت البلد، وتختلف تقديراتهم بين نحو ٢٫٠ و٣٫٣ كغ بحسب الصنف والمكيال."}],"kh":[{"t":"إخراج القيمة في زكاة الفطر","n":"ثبت النص بإخراج الطعام.","p":[["الحنفية","يجوز إخراج القيمة نقداً."],["الجمهور (المالكية والشافعية والحنابلة)","لا يجزئ إلا الطعام من قوت البلد."]]},{"t":"تقديم زكاة الفطر","n":"ثبت أن الصحابة كانوا يعطونها قبل العيد بيوم أو يومين.","p":[["المالكية والحنابلة","تُقدَّم قبل العيد بيوم أو يومين."],["الشافعية","يجوز إخراجها من أول رمضان."]]}]}],"h":[{"id":"m-arkan","t":"بني الإسلام على خمس","x":"بُنِيَ الإِسْلاَمُ عَلَى خَمْسٍ شَهَادَةِ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامِ الصَّلاَةِ، وَإِيتَاءِ الزَّكَاةِ، وَالْحَجِّ، وَصَوْمِ رَمَضَانَ","src":[["bukhari","8"],["muslim","16"]],"gr":"صحيح: متفق عليه","dg":"","f":"من أصول الدين: الشهادتان، والصلاة، والزكاة، والحج، وصوم رمضان.","en":"Ibn Umar ؓ said the Messenger of Allah ﷺ said: \"Islam is built on five: the testimony that there is no god but Allah and that Muhammad is the Messenger of Allah, establishing prayer, paying zakat, the pilgrimage, and fasting Ramadan.\"","ch":"arkan"},{"id":"m-ruya","t":"صوموا لرؤيته وأفطروا لرؤيته","x":"الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا - ثُمَّ عَقَدَ إِبْهَامَهُ فِي الثَّالِثَةِ - فَصُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ أُغْمِيَ عَلَيْكُمْ فَاقْدِرُوا لَهُ ثَلاَثِينَ","src":[["muslim","1080"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يقرر الحديث اعتماد الرؤية أو إكمال العدة ثلاثين.","en":"The Prophet ﷺ said: \"The month is thus and thus and thus,\" folding his thumb on the third. \"Fast when you see it and break the fast when you see it; if it is obscured from you, then complete it as thirty.\"","ch":"siyam"},{"id":"m-niyya","t":"من لم يجمع الصيام قبل الفجر","x":"مَنْ لَمْ يُجْمِعِ الصِّيَامَ قَبْلَ الْفَجْرِ فَلاَ صِيَامَ لَهُ","src":[["abudawud","2454"],["tirmidhi","730"],["nasai","2338"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: ضعيف","f":"أصل مسألة تبييت النية، وللعلماء خلاف في رفعه ووقفه فتُنظر درجته أدناه.","en":"Hafsa ؓ reported the Prophet ﷺ said: \"Whoever does not resolve to fast before dawn has no fast.\"","ch":"siyam"},{"id":"m-suhur","t":"تسحروا فإن في السحور بركة","x":"تَسَحَّرُوا فَإِنَّ فِي السَّحُورِ بَرَكَةً","src":[["bukhari","1923"],["muslim","1095"]],"gr":"صحيح: متفق عليه","dg":"","f":"السحور سنة وبركة، حتى لو كان جرعة ماء.","en":"Anas ؓ said the Prophet ﷺ said: \"Eat suhur, for in suhur there is blessing.\"","ch":"siyam"},{"id":"m-fitr","t":"لا يزال الناس بخير ما عجلوا الفطر","x":"لاَ يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ","src":[["bukhari","1957"],["muslim","1098"]],"gr":"صحيح: متفق عليه","dg":"","f":"تعجيل الفطر من هدي النبي ﷺ ومخالفة لمن يؤخره.","en":"Sahl ibn Sa'd ؓ said the Messenger of Allah ﷺ said: \"People will remain in good as long as they hasten to break the fast.\"","ch":"siyam"},{"id":"m-taqdim","t":"لا تقدموا رمضان بصوم يوم ولا يومين","x":"لاَ تَقَدَّمُوا رَمَضَانَ بِصَوْمِ يَوْمٍ وَلاَ يَوْمَيْنِ إِلاَّ رَجُلٌ كَانَ يَصُومُ صَوْمًا فَلْيَصُمْهُ","src":[["muslim","1082"]],"gr":"صحيح: رواه مسلم","dg":"","f":"النهي عن استقبال رمضان بصوم يوم أو يومين احتياطاً، واستثناء من كانت له عادة صيام.","en":"Abu Hurayra ؓ said the Messenger of Allah ﷺ said: \"Do not precede Ramadan by fasting a day or two, except for a man who was accustomed to fasting a certain fast; then let him fast it.\"","ch":"siyam"},{"id":"m-nasi","t":"من نسي وهو صائم فأكل أو شرب","x":"مَنْ نَسِيَ وَهُوَ صَائِمٌ فَأَكَلَ أَوْ شَرِبَ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ","src":[["muslim","1155"]],"gr":"صحيح: رواه مسلم","dg":"","f":"رحمة بالناسي: الصوم صحيح، وما أكله فهو رزق ساقه الله إليه.","en":"Abu Hurayra ؓ said the Messenger of Allah ﷺ said: \"Whoever forgets while fasting and eats or drinks, let him complete his fast, for Allah has fed him and given him drink.\"","ch":"mufattirat"},{"id":"m-kaffara","t":"كفارة المجامع في رمضان","x":"هَلْ تَجِدُ رَقَبَةً تُعْتِقُهَا \". قَالَ لاَ. قَالَ \" فَهَلْ تَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ \". قَالَ لاَ. فَقَالَ \" فَهَلْ تَجِدُ إِطْعَامَ سِتِّينَ مِسْكِينًا","src":[["bukhari","1936"]],"gr":"صحيح: رواه البخاري","dg":"","f":"من حديث أبي هريرة ﵁ في الرجل الذي وقع على امرأته: الترتيب في الكفارة وسعة رحمة النبي ﷺ.","en":"Abu Hurayra ؓ said a man came and said: Messenger of Allah, I am ruined. He said: \"What is the matter?\" He said: I had intercourse with my wife while fasting. The Messenger of Allah ﷺ said: \"Can you free a slave?\" He said no. \"Can you fast two consecutive months?\" He said no. \"Can you feed sixty poor people?\" He said no.","ch":"mufattirat"},{"id":"m-qay","t":"من ذرعه القيء","x":"مَنْ ذَرَعَهُ الْقَىْءُ فَلَيْسَ عَلَيْهِ قَضَاءٌ وَمَنِ اسْتَقَاءَ عَمْدًا فَلْيَقْضِ","src":[["tirmidhi","720"]],"gr":"","dg":"الألباني: صحيح؛ أحمد شاكر: صحيح؛ بشار عواد معروف: ضعيف؛ زبير علي زئي: ضعيف","f":"يفرق بين من غلبه القيء فلا قضاء عليه، ومن تعمده فعليه القضاء.","en":"Abu Hurayra ؓ said the Prophet ﷺ said: \"Whoever is overcome by vomiting has no making up to do, and whoever vomits deliberately must make up.\"","ch":"mufattirat"},{"id":"m-hijama","t":"أفطر الحاجم والمحجوم","x":"أَفْطَرَ الْحَاجِمُ وَالْمَحْجُومُ","src":[["abudawud","2367"]],"gr":"","dg":"الألباني: صحيح؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده صحيح","f":"أحد الحديثين في مسألة الحجامة؛ ويُنظر إلى حديث ابن عباس بعده وإلى خلاف الفقهاء أعلاه.","en":"Thawban ؓ reported the Prophet ﷺ said: \"The cupper and the one cupped have broken their fast.\"","ch":"mufattirat"},{"id":"m-ihtajama","t":"احتجم وهو صائم","x":"احْتَجَمَ، وَهْوَ مُحْرِمٌ وَاحْتَجَمَ وَهْوَ صَائِمٌ","src":[["bukhari","1938"]],"gr":"صحيح: رواه البخاري","dg":"","f":"الحديث الآخر في الباب؛ وبه احتج من رأى أن الحجامة لا تفطر.","en":"Ibn Abbas ؓ reported that the Prophet ﷺ was cupped while in ihram and was cupped while fasting.","ch":"mufattirat"},{"id":"m-safar","t":"الصائم والمفطر في السفر","x":"كُنَّا نَغْزُو مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم فِي رَمَضَانَ فَمِنَّا الصَّائِمُ وَمِنَّا الْمُفْطِرُ فَلاَ يَجِدُ الصَّائِمُ","src":[["muslim","1116"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يبيّن أن الصحابة كانوا يختلفون في السفر بين الصوم والفطر ولا يعيب أحدهما على الآخر.","en":"Abu Sa'id al-Khudri ؓ said: We used to campaign with the Messenger of Allah ﷺ in Ramadan; some of us fasted and some did not, and the one who fasted did not criticise the one who did not, nor the other him.","ch":"mufattirat"},{"id":"m-iman","t":"من صام رمضان إيماناً واحتساباً","x":"مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ","src":[["bukhari","38"],["muslim","760"]],"gr":"صحيح: متفق عليه","dg":"","f":"جعل الإيمان والاحتساب شرطاً لهذا الجزاء: صدق النية وطلب الأجر.","en":"Abu Hurayra ؓ said the Prophet ﷺ said: \"Whoever fasts Ramadan out of faith and seeking reward, his previous sins will be forgiven.\"","ch":"adab-siyam"},{"id":"m-junna","t":"كل عمل ابن آدم له إلا الصيام","x":"قَالَ اللَّهُ كُلُّ عَمَلِ ابْنِ آدَمَ لَهُ إِلاَّ الصِّيَامَ، فَإِنَّهُ لِي، وَأَنَا أَجْزِي بِهِ. وَالصِّيَامُ جُنَّةٌ، وَإِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ، فَلاَ يَرْفُثْ وَلاَ يَصْخَبْ، فَإِنْ سَابَّهُ أَحَدٌ، أَوْ قَاتَلَهُ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ. وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَخُلُوفُ فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ، لِلصَّائِمِ فَرْحَتَانِ يَفْرَحُهُمَا إِذَا أَفْطَرَ فَرِحَ، وَإِذَا لَقِيَ رَبَّهُ فَرِحَ بِصَوْمِهِ","src":[["bukhari","1904"],["muslim","1151"]],"gr":"صحيح: متفق عليه","dg":"","f":"اختصّ الله الصيام بنسبته إليه وتولى جزاءه بنفسه، وللصائم فرحتان.","en":"The Prophet ﷺ said: \"Allah said: Every deed of the son of Adam is for him except fasting; it is for Me and I reward it. Fasting is a shield. When the day of fasting of any of you comes, let him not speak obscenely or clamour, and if anyone insults or fights him let him say: I am fasting. By the One in whose hand is Muhammad's soul, the breath of the fasting person's mouth is better with Allah than the scent of musk. The fasting person has two joys: when he breaks his fast he rejoices, and when he meets his Lord he rejoices in his fast.\"","ch":"adab-siyam"},{"id":"m-zur","t":"من لم يدع قول الزور","x":"مَنْ لَمْ يَدَعْ قَوْلَ الزُّورِ وَالْعَمَلَ بِهِ فَلَيْسَ لِلَّهِ حَاجَةٌ فِي أَنْ يَدَعَ طَعَامَهُ وَشَرَابَهُ","src":[["bukhari","1903"]],"gr":"صحيح: رواه البخاري","dg":"","f":"غاية الصيام التقوى لا مجرد الإمساك عن الطعام والشراب.","en":"Abu Hurayra ؓ said the Prophet ﷺ said: \"Whoever does not give up false speech and acting upon it, Allah has no need of his giving up his food and drink.\"","ch":"adab-siyam"},{"id":"m-ashr","t":"العشر الأواخر","x":"إِذَا دَخَلَ الْعَشْرُ شَدَّ مِئْزَرَهُ، وَأَحْيَا لَيْلَهُ، وَأَيْقَظَ أَهْلَهُ","src":[["bukhari","2024"]],"gr":"صحيح: رواه البخاري","dg":"","f":"كان النبي ﷺ يضاعف جهده في العشر الأواخر ويحيي ليله ويوقظ أهله.","en":"Aisha ؓ said: When the last ten nights began, the Prophet ﷺ would tighten his waist-wrapper, spend the night in worship and wake his family.","ch":"adab-siyam"},{"id":"m-qadr","t":"التماس ليلة القدر","x":"تَحَرَّوْا لَيْلَةَ الْقَدْرِ فِي الْوِتْرِ مِنَ الْعَشْرِ الأَوَاخِرِ","src":[["bukhari","2017"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ليلة القدر في العشر الأواخر، والأرجح في أوتارها، فيُجتهد فيها كلها.","en":"Aisha ؓ said the Messenger of Allah ﷺ said: \"Seek Laylat al-Qadr in the odd nights of the last ten of Ramadan.\"","ch":"adab-siyam"},{"id":"m-sitt","t":"ست من شوال","x":"مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتًّا مِنْ شَوَّالٍ كَانَ كَصِيَامِ الدَّهْرِ","src":[["muslim","1164"]],"gr":"صحيح: رواه مسلم","dg":"","f":"أصل استحباب ستة أيام من شوال؛ وللمالكية فيها كلام أعلاه.","en":"Abu Ayyub ؓ said the Messenger of Allah ﷺ said: \"Whoever fasts Ramadan and follows it with six days of Shawwal, it is like fasting a lifetime.\"","ch":"adab-siyam"},{"id":"m-arafa","t":"صيام يوم عرفة وعاشوراء","x":"صِيَامُ يَوْمِ عَرَفَةَ أَحْتَسِبُ عَلَى اللَّهِ أَنْ يُكَفِّرَ السَّنَةَ الَّتِي قَبْلَهُ وَالسَّنَةَ الَّتِي بَعْدَهُ","src":[["muslim","1162"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يوم عرفة يكفّر السنتين، وعاشوراء السنة الماضية، لما ورد في الحديث نفسه.","en":"The Prophet ﷺ said: \"Fasting the Day of Arafah, I hope from Allah that it expiates the year before it and the year after it.\"","ch":"adab-siyam"},{"id":"m-thalatha","t":"ثلاثة أيام من كل شهر","x":"أَوْصَانِي خَلِيلِي صلى الله عليه وسلم بِثَلاَثٍ صِيَامِ ثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَرَكْعَتَىِ الضُّحَى، وَأَنْ أُوتِرَ قَبْلَ أَنْ أَنَامَ","src":[["bukhari","1981"],["muslim","721"]],"gr":"صحيح: متفق عليه","dg":"","f":"وصية النبي ﷺ لأبي هريرة ﵁: ثلاثة أيام، وركعتا الضحى، والوتر قبل النوم.","en":"Abu Hurayra ؓ said: My beloved friend ﷺ advised me to do three things: fasting three days of every month, two units of the forenoon prayer, and to pray witr before sleeping.","ch":"adab-siyam"},{"id":"m-zakat-wid","t":"من آتاه الله مالاً فلم يؤد زكاته","x":"مَنْ آتَاهُ اللَّهُ مَالاً فَلَمْ يُؤَدِّ زَكَاتَهُ، مُثِّلَ لَهُ مَالُهُ شُجَاعًا أَقْرَعَ، لَهُ زَبِيبَتَانِ يُطَوَّقُهُ يَوْمَ الْقِيَامَةِ، يَأْخُذُ بِلِهْزِمَتَيْهِ ـ يَعْنِي بِشِدْقَيْهِ ـ يَقُولُ أَنَا مَالُكَ أَنَا كَنْزُكَ","src":[["bukhari","4565"]],"gr":"صحيح: رواه البخاري","dg":"","f":"وعيد لمن منع الزكاة، يُمثَّل ماله له يوم القيامة.","en":"Abu Hurayra ؓ said the Prophet ﷺ said: \"Whoever Allah gives wealth and he does not pay its zakat, his wealth will be made for him on the Day of Resurrection into a bald, venomous snake with two black spots above its eyes, which will be wrapped around his neck, then seize his jaws and say: I am your wealth, I am your treasure.\"","ch":"zakat"},{"id":"m-nisab","t":"النصب الثلاثة","x":"لَيْسَ فِيمَا دُونَ خَمْسِ أَوَاقٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ ذَوْدٍ صَدَقَةٌ، وَلَيْسَ فِيمَا دُونَ خَمْسِ أَوْسُقٍ","src":[["bukhari","1405"],["muslim","979"]],"gr":"صحيح: متفق عليه","dg":"","f":"أقل النصاب: خمس أواق من الفضة، وخمس ذود من الإبل، وخمسة أوسق من الحبوب والثمار.","en":"Abu Sa'id al-Khudri ؓ said the Prophet ﷺ said: \"There is no charity on less than five uqiyyas of silver, no charity on less than five camels, and no charity on less than five wasqs.\"","ch":"zakat"},{"id":"m-ushr","t":"العشر ونصف العشر","x":"فِيمَا سَقَتِ السَّمَاءُ وَالْعُيُونُ أَوْ كَانَ عَثَرِيًّا الْعُشْرُ، وَمَا سُقِيَ بِالنَّضْحِ نِصْفُ الْعُشْرِ","src":[["bukhari","1483"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يفرّق بين ما سُقي بلا كلفة وما سُقي بكلفة.","en":"The Prophet ﷺ said: \"On what is watered by the sky and springs, or by flowing water, one-tenth; and on what is watered by the water-wheel, one-twentieth.\"","ch":"zakat"},{"id":"m-riqa","t":"في الرقة ربع العشر","x":"وَفِي الرِّقَةِ رُبْعُ الْعُشْرِ، فَإِنْ لَمْ تَكُنْ إِلاَّ تِسْعِينَ وَمِائَةً فَلَيْسَ فِيهَا شَىْءٌ، إِلاَّ أَنْ يَشَاءَ رَبُّهَا","src":[["bukhari","1454"]],"gr":"صحيح: رواه البخاري","dg":"","f":"من كتاب أبي بكر ﵁ في فريضة الصدقة: ربع العشر في الفضة، ولا زكاة فيما دون النصاب إلا أن يشاء صاحبه.","en":"From Abu Bakr's ؓ letter on the obligatory charity: \"And on silver, one-fortieth; and if it is only one hundred and ninety there is nothing due, unless its owner wishes.\"","ch":"zakat"},{"id":"m-anam","t":"فريضة الصدقة في الإبل والغنم","x":"فِي أَرْبَعٍ وَعِشْرِينَ مِنَ الإِبِلِ فَمَا دُونَهَا مِنَ الْغَنَمِ مِنْ كُلِّ خَمْسٍ شَاةٌ، إِذَا بَلَغَتْ خَمْسًا وَعِشْرِينَ إِلَى خَمْسٍ وَثَلاَثِينَ فَفِيهَا بِنْتُ مَخَاضٍ أُنْثَى، فَإِذَا بَلَغَتْ سِتًّا وَثَلاَثِينَ إِلَى خَمْسٍ وَأَرْبَعِينَ فَفِيهَا بِنْتُ لَبُونٍ أُنْثَى، فَإِذَا بَلَغَتْ سِتًّا وَأَرْبَعِينَ إِلَى سِتِّينَ فَفِيهَا حِقَّةٌ طَرُوقَةُ الْجَمَلِ، فَإِذَا بَلَغَتْ وَاحِدَةً وَسِتِّينَ إِلَى خَمْسٍ وَسَبْعِينَ فَفِيهَا جَذَعَةٌ، فَإِذَا بَلَغَتْ ـ يَعْنِي ـ سِتًّا وَسَبْعِينَ إِلَى تِسْعِينَ فَفِيهَا بِنْتَا لَبُونٍ، فَإِذَا بَلَغَتْ إِحْدَى وَتِسْعِينَ إِلَى عِشْرِينَ وَمِائَةٍ فَفِيهَا حِقَّتَانِ طَرُوقَتَا الْجَمَلِ، فَإِذَا زَادَتْ عَلَى عِشْرِينَ وَمِائَةٍ فَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ، وَفِي كُلِّ خَمْسِينَ حِقَّةٌ، وَمَنْ لَمْ يَكُنْ مَعَهُ إِلاَّ أَرْبَعٌ مِنَ الإِبِلِ فَلَيْسَ فِيهَا صَدَقَةٌ، إِلاَّ أَنْ يَشَاءَ رَبُّهَا، فَإِذَا بَلَغَتْ خَمْسًا مِنَ الإِبِلِ فَفِيهَا شَاةٌ، وَفِي صَدَقَةِ الْغَنَمِ فِي سَائِمَتِهَا إِذَا كَانَتْ أَرْبَعِينَ إِلَى عِشْرِينَ وَمِائَةٍ شَاةٌ، فَإِذَا زَادَتْ عَلَى عِشْرِينَ وَمِائَةٍ إِلَى مِائَتَيْنِ شَاتَانِ، فَإِذَا زَادَتْ عَلَى مِائَتَيْنِ إِلَى ثَلاَثِمِائَةٍ فَفِيهَا ثَلاَثٌ، فَإِذَا زَادَتْ عَلَى ثَلاَثِمِائَةٍ فَفِي كُلِّ مِائَةٍ شَاةٌ","src":[["bukhari","1454"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تفصيل نصب الإبل والغنم من كتاب أبي بكر ﵁ الذي كتبه لأنس ﵁ لما وجهه إلى البحرين.","en":"From Abu Bakr's ؓ letter: \"On twenty-four camels and fewer, one sheep for every five; when they reach twenty-five to thirty-five, a she-camel in her second year; from thirty-six to forty-five, a she-camel in her third year; from forty-six to sixty, a she-camel in her fourth year... and on sheep grazing freely, when they are forty to one hundred and twenty, one sheep; above one hundred and twenty to two hundred, two sheep; above two hundred to three hundred, three; above three hundred, one sheep for every hundred.\"","ch":"zakat"},{"id":"m-abd","t":"ليس على المسلم في عبده ولا فرسه صدقة","x":"لَيْسَ عَلَى الْمُسْلِمِ فِي عَبْدِهِ وَلاَ فَرَسِهِ صَدَقَةٌ","src":[["muslim","982"]],"gr":"صحيح: رواه مسلم","dg":"","f":"ما يُقتنى للخدمة والاستعمال لا زكاة فيه.","en":"Abu Hurayra ؓ said the Messenger of Allah ﷺ said: \"There is no charity due from a Muslim on his slave or his horse.\"","ch":"zakat"},{"id":"m-malakan","t":"اللهم أعط منفقاً خلفاً","x":"مَا مِنْ يَوْمٍ يُصْبِحُ الْعِبَادُ فِيهِ إِلاَّ مَلَكَانِ يَنْزِلاَنِ فَيَقُولُ أَحَدُهُمَا اللَّهُمَّ أَعْطِ مُنْفِقًا خَلَفًا، وَيَقُولُ الآخَرُ اللَّهُمَّ أَعْطِ مُمْسِكًا تَلَفًا","src":[["bukhari","1442"],["muslim","1010"]],"gr":"صحيح: متفق عليه","dg":"","f":"فضل الإنفاق وسوء المنع.","en":"Abu Hurayra ؓ said the Prophet ﷺ said: \"There is no day on which servants rise but two angels descend; one says: O Allah, give the one who spends a replacement, and the other says: O Allah, give the one who withholds destruction.\"","ch":"zakat"},{"id":"m-fitr-sa","t":"فرض زكاة الفطر","x":"فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ صَاعًا مِنْ تَمْرٍ، أَوْ صَاعًا مِنْ شَعِيرٍ عَلَى الْعَبْدِ وَالْحُرِّ، وَالذَّكَرِ وَالأُنْثَى، وَالصَّغِيرِ وَالْكَبِيرِ مِنَ الْمُسْلِمِينَ","src":[["bukhari","1503"],["muslim","984"]],"gr":"صحيح: متفق عليه","dg":"","f":"أصل زكاة الفطر وقدرها ومن تجب عليهم.","en":"Ibn Umar ؓ said: The Messenger of Allah ﷺ prescribed zakat al-fitr: a sa' of dates or a sa' of barley, on slave and free, male and female, young and old of the Muslims; and he ordered that it be paid before people go out to the prayer.","ch":"masarif"},{"id":"m-fitr-tuhra","t":"طهرة للصائم وطعمة للمساكين","x":"فَرَضَ رَسُولُ اللَّهِ صلى الله عليه وسلم زَكَاةَ الْفِطْرِ طُهْرَةً لِلصَّائِمِ مِنَ اللَّغْوِ وَالرَّفَثِ وَطُعْمَةً لِلْمَسَاكِينِ مَنْ أَدَّاهَا قَبْلَ الصَّلاَةِ فَهِيَ زَكَاةٌ مَقْبُولَةٌ وَمَنْ أَدَّاهَا بَعْدَ الصَّلاَةِ فَهِيَ صَدَقَةٌ مِنَ الصَّدَقَاتِ","src":[["abudawud","1609"],["ibnmajah","1827"]],"gr":"","dg":"الألباني: حسن؛ شعيب الأرنؤوط: حسن؛ محيي الدين عبد الحميد: حسن؛ زبير علي زئي: إسناده حسن","f":"يبيّن حكمة زكاة الفطر ووقتها المعتبر قبل الصلاة.","en":"Ibn Abbas ؓ said: The Messenger of Allah ﷺ prescribed zakat al-fitr as a purification for the fasting person from idle talk and indecency and as food for the poor; whoever pays it before the prayer, it is accepted zakat, and whoever pays it after the prayer, it is a charity among charities.","ch":"masarif"},{"id":"m-ghani","t":"لا تحل الصدقة لغني","x":"لاَ تَحِلُّ الصَّدَقَةُ لِغَنِيٍّ وَلاَ لِذِي مِرَّةٍ سَوِيٍّ","src":[["abudawud","1634"],["tirmidhi","652"]],"gr":"","dg":"الألباني: صحيح؛ شعيب الأرنؤوط: حسن؛ محيي الدين عبد الحميد: صحيح؛ زبير علي زئي: إسناده حسن","f":"الغني والقوي المكتسب لا يستحقان من الزكاة.","en":"Abdullah ibn Amr ؓ reported the Prophet ﷺ said: \"Charity is not permissible for a rich person nor for one who is strong and sound.\"","ch":"masarif"}],"q":[{"ch":"siyam","w":"السعدي","bk":"saadi","s":2,"ay":183,"x":"ثم ذكر تعالى حكمته في مشروعية الصيام فقال:{لعلكم تتقون}؛ فإن الصيام من أكبر أسباب التقوى لأن فيه امتثال أمر الله واجتناب نهيه، فممِّا اشتمل عليه من التقوى أن الصائم يترك ما حرم الله عليه من الأكل والشرب والجماع ونحوها التي تميل إليها نفسه متقرباً بذلك إلى الله راجياً بتركها ثوابه، فهذا من التقوى، ومنها: أن الصائم يدرب نفسه على مراقبة الله تعالى فيترك ما تهوى نفسه مع قدرته عليه لعلمه باطلاع الله عليه، ومنها: أنَّ الصيام يضيق مجاري الشيطان فإنه يجري من ابن ادم مجرى الدم فبالصيام يضعف نفوذه وتقل منه المعاصي، ومنها: أن الصائم في الغالب تكثر طاعته والطاعات من خصال التقوى، ومنها: أن الغني إذا ذاق ألم الجوع أوجب له ذلك مواساة الفقراء المعدمين. وهذا من خصال التقوى","n":"حكمة مشروعية الصيام: التقوى.","en":"\"Then He mentioned its wisdom: so that you may become God-conscious. Fasting is among the greatest causes of taqwa because it involves obeying Allah's command and avoiding His prohibition... The rich man who tastes the pain of hunger is moved to console the destitute poor; and this is among the traits of taqwa.\""},{"ch":"adab-siyam","w":"السعدي","bk":"saadi","s":97,"ay":3,"x":"ثم فخَّم شأنها وعظَّم مقدارها، فقال:{وما أدراكَ ما ليلةُ القَدۡرِ}؛ أي: فإنَّ شأنها جليلٌ، وخطرها عظيمٌ. {3}{ليلةُ القدرِ خيرٌ من ألفِ شهرٍ}؛ أي: تعادل من فضلها ألف شهرٍ، فالعمل الذي يقع فيها خيرٌ من العمل في ألف شهرٍ خاليةٍ منها، وهذا مما تتحيَّر فيه الألباب، وتندهش","n":"عظمة ليلة القدر وأنها خير من ألف شهر.","en":"\"Then He magnified its status and elevated its worth: And what will make you know what the Night of Decree is? Its matter is lofty and its weight is great. The Night of Decree is better than a thousand months: its merit equals a thousand months, so a deed done in it is better than a deed in a thousand months without it.\""},{"ch":"masarif","w":"السعدي","bk":"saadi","s":9,"ay":60,"x":"وهم ثمانية أصناف: الأول والثاني: الفقراء والمساكين، وهم في هذا الموضع صنفان متفاوتان؛ فالفقير أشدُّ حاجةً من المسكين؛ لأنَّ الله بدأ بهم، ولا يُبدأ إلا بالأهمِّ فالأهمِّ؛ فَفُسِّرَ الفقير بأنه الذي لا يجد شيئاً أو يجد بعض كفايته دون نصفها، والمسكين الذي يجد نصفها فأكثر، ولا يجد تمام كفايته؛ لأنَه لو وجدها؛ لكان غنيًّا، فيعطَون من الزكاة ما يزول به فقرهم ومسكنتهم","n":"تفسير الصنفين الأولين.","en":"\"And they are eight categories. The first and second: the poor and the needy, here two categories differing in degree; the poor is in greater need than the needy... they are given from zakat what removes their poverty and neediness.\""}],"ay":{"189":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُتِبَ عَلَيۡكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ","190":"أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","191":"شَهۡرُ رَمَضَانَ ٱلَّذِيٓ أُنزِلَ فِيهِ ٱلۡقُرۡءَانُ هُدٗى لِّلنَّاسِ وَبَيِّنَٰتٖ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡيَصُمۡهُۖ وَمَن كَانَ مَرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۗ يُرِيدُ ٱللَّهُ بِكُمُ ٱلۡيُسۡرَ وَلَا يُرِيدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُواْ ٱلۡعِدَّةَ وَلِتُكَبِّرُواْ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ","193":"أُحِلَّ لَكُمۡ لَيۡلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمۡۚ هُنَّ لِبَاسٞ لَّكُمۡ وَأَنتُمۡ لِبَاسٞ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَيۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٰٔنَ بَٰشِرُوهُنَّ وَٱبۡتَغُواْ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُواْ وَٱشۡرَبُواْ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلۡخَيۡطُ ٱلۡأَبۡيَضُ مِنَ ٱلۡخَيۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمۡ عَٰكِفُونَ فِي ٱلۡمَسَٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ يَتَّقُونَ","273":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَنفِقُواْ مِن طَيِّبَٰتِ مَا كَسَبۡتُمۡ وَمِمَّآ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَيَمَّمُواْ ٱلۡخَبِيثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغۡمِضُواْ فِيهِۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَنِيٌّ حَمِيدٌ","389":"فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ","1268":"۞ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ كَثِيرٗا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَيَأۡكُلُونَ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۗ وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٖ","1269":"يَوۡمَ يُحۡمَىٰ عَلَيۡهَا فِي نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُواْ مَا كُنتُمۡ تَكۡنِزُونَ","1294":"۞ إِنَّمَا ٱلصَّدَقَٰتُ لِلۡفُقَرَآءِ وَٱلۡمَسَٰكِينِ وَٱلۡعَٰمِلِينَ عَلَيۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِي ٱلرِّقَابِ وَٱلۡغَٰرِمِينَ وَفِي سَبِيلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِيلِۖ فَرِيضَةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","1337":"خُذۡ مِنۡ أَمۡوَٰلِهِمۡ صَدَقَةٗ تُطَهِّرُهُمۡ وَتُزَكِّيهِم بِهَا وَصَلِّ عَلَيۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنٞ لَّهُمۡۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ","6125":"إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ","6126":"وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ","6127":"لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٞ مِّنۡ أَلۡفِ شَهۡرٖ","6128":"تَنَزَّلُ ٱلۡمَلَٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ","6129":"سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ"},"nay":18}};
/* مشكاة · أدعية المناسبات (#adiya) والمناسك والعبادات (#manasik): يُحمَّل عند أول فتح من fiqh.js.
   نص الآيات بلفظ مصحف المدينة (مجمع الملك فهد، الإصدار ١٨) وبخطه، والأحاديث مقتطعة بلفظها من الكتب الستة المضمّنة (data/hadith)
   بترقيمها ودرجتها، ونقول المفسرين بلفظها من data/t؛ والبيانات تُبنى بسكربت من هذه المصادر، فلا يُكتب نص منسوب باليد.
   الخلاف المعتبر بين المذاهب يُنقل بأقوال أصحابه دون ترجيح من عندنا. يعمل كاملاً دون إنترنت ولا يتصل بأي جهة خارجية. */
window.fiqhRender = function (key) {
  const D = FQ[key], enOn = LANG !== 'ar', bk = k => (HAD_BOOKS[k] || [k])[0];
  const AR = x => String(x).replace(/\d/g, d => '٠١٢٣٤٥٦٧٨٩'[d]);
  const num = k => LANG === 'ar' ? AR(k) : k;
  const CFG = {
    adiya: {
      eyebrow: 'احفظ وتعبّد', h1: 'أدعية القرآن والسنة بالمناسبة', cls: 'fq-adiya',
      lead: 'أدعية قرآنية ونبوية مرتبة بمناسباتها: الكرب والمرض والسفر والنوم والصلاة وليلة القدر وغيرها، بنص المصحف والأحاديث الصحيحة بتخريجها ودرجتها، وأقوال المفسرين بنصها.',
      stats: [[D.ch.length, 'مناسبة'], [D.nay, 'آية'], [D.h.length, 'حديثاً'], [D.q.length, 'نقلاً']],
      note: ['تنبيه', 'هذا القسم يعرض الأدعية الواردة في القرآن والسنة الصحيحة بنصوصها. لا نذكر فضلاً لدعاء إلا بلفظ الحديث نفسه، وتجد درجة كل حديث بحسب أحكام المحدّثين المنقولة في الكتب المضمّنة.'],
      searchLbl: 'ابحث في الأدعية', searchHint: 'اكتب كلمة من الدعاء أو مناسبته لتصفية البطاقات.',
      cross: ['أدعية القرآن', 'قسم «أدعية القرآن» يضم كل ما دعا به الأنبياء والصالحون في القرآن بموضوعاته، وهنا الأدعية مرتبة بالمناسبة مع السنة.', 'duaa', 'افتح قسم أدعية القرآن'],
      foot: 'نصوص الآيات بلفظ مصحف المدينة النبوية (مجمع الملك فهد، الإصدار ١٨) وبخطه، ونصوص الأحاديث من الكتب الستة المضمّنة بترقيمها ودرجتها، ونقول المفسرين بلفظها من كتبهم المضمّنة؛ أما التمهيدات والفوائد فصياغة موجزة.'
    },
    ibadat: {
      eyebrow: 'احفظ وتعبّد', h1: 'فقه العبادات: الصيام والزكاة', cls: 'fq-ibadat',
      lead: 'أحكام الصيام والزكاة بإرشاد خطوة بخطوة من الآيات والأحاديث الصحيحة وأقوال المفسرين، مع ذكر الخلاف المعتبر بين المذاهب دون ترجيح من عندنا.',
      stats: [[D.ch.length, 'باباً'], [D.ch.reduce((t, c) => t + (c.st || []).length, 0), 'خطوة'], [D.ch.reduce((t, c) => t + (c.kh || []).length, 0), 'خلافاً'], [D.h.length, 'حديثاً']],
      note: ['تنبيه مهم', 'هذا القسم دليل تعليمي موجز لا يغني عن سؤال أهل العلم ولا عن شرح مرشد الحملة؛ ولكل مذهب تفاصيله، ونقول الخلاف فيه بأقوال أصحابه دون ترجيح. '],
      searchLbl: 'ابحث في فقه العبادات', searchHint: 'اكتب كلمة (نية، كفارة، نصاب…) لتصفية الخطوات والأحاديث.',
      cross: ['ركن الحج والعمرة', 'ركن «الحج والعمرة» يشرح المناسك خطوة بخطوة بالأحاديث والخلاف والرسوم.', 'hajj', 'افتح ركن الحج والعمرة'],
      foot: 'نصوص الآيات بلفظ مصحف المدينة النبوية (مجمع الملك فهد، الإصدار ١٨) وبخطه، ونصوص الأحاديث من الكتب الستة المضمّنة بترقيمها ودرجتها، ونقول المفسرين بلفظها من كتبهم المضمّنة؛ أما الخطوات والفوائد فصياغة موجزة للمتفق عليه، ويُعرض الخلاف بأقوال أصحابه دون ترجيح من عندنا.'
    }
  }[key];
  const ayLine = i => { const a = Q.ayat[i]; return `<div class="ayah tm-q"><span class="tm-t">${esc(D.ay[i] || ayahText(i))}</span> <span class="num tm-n" data-ayah="${i}" title="${esc(ref(i))}">${AR(a[1])}</span></div>`; };
  const ays = ([s, a, b]) => { const o = [], last = Math.min(b || a, a + 6); for (let q = a; q <= last; q++) { const i = idxOf(s, q); if (i >= 0) o.push(ayLine(i)); } if ((b || a) > last) o.push(`<a class="btn th-more" href="#a${s}-${last + 1}">أكمل الآيات في المصحف</a>`); return o.join(''); };
  const refOf = r => `${refLink(idxOf(r[0], r[1]))}${r[2] ? `<span>–${n(r[2])}</span>` : ''}`;
  const ayCard = it => `<article class="tm-ay fq-c"><h3>${it.t}</h3><div class="u-ref">${refOf(it.r)}</div>
    <div class="tm-ays">${ays(it.r)}</div><p class="tm-note">${esc(it.n)}</p>
    <div class="tm-links"><a class="btn" href="#pa${idxOf(it.r[0], it.r[1])}"><svg><use href="#i-book"/></svg>افتح في المصحف</a></div></article>`;
  const hCard = h => `<article class="tm-h fq-c" id="fq-${h.id}"><h3>${h.t}</h3>
    <blockquote class="tm-matn notranslate" translate="no" lang="ar" dir="rtl">${esc(h.x)}</blockquote>
    ${enOn ? `<div class="tm-en"><b>معنى الحديث بالإنجليزية</b><p class="notranslate" translate="no" lang="en" dir="ltr">${esc(h.en)}</p></div>` : ''}
    <p class="tm-tx"><span>رواه</span> ${h.src.map(([b, k]) => `<b>${bk(b)}</b> <span class="num">(${num(k)})</span>`).join(' · ')}</p>
    ${h.gr || h.dg ? `<p class="tm-gr"><span>درجته</span> ${h.gr ? `<em class="tm-badge">${h.gr}</em>` : ''}${h.dg ? `<span class="tm-dg notranslate" translate="no">${esc(h.dg.replace(/[؛\s]+$/, ''))}</span>` : ''}</p>` : ''}
    <div class="th-use"><b>فقه الحديث</b><p>${esc(h.f)}</p></div></article>`;
  const qCard = q => { const b = TF.find(x => x.key === q.bk);
    return `<figure class="qs-quote tm-qt fq-c"><blockquote class="notranslate" translate="no" lang="ar" dir="rtl">${esc(q.x)}</blockquote>
    ${enOn ? `<p class="tm-qen notranslate" translate="no" lang="en" dir="ltr">${esc(q.en)}</p>` : ''}
    <figcaption><b>${q.w}</b> · <span>نقل بلفظه من</span> <span>${esc(b ? b.title : q.bk)}</span> · <span>عند تفسير</span> ${refLink(idxOf(q.s, q.ay))}</figcaption>
    <p class="tm-note small">${esc(q.n)}</p></figure>`; };
  const stepsHtml = c => c.st ? `<h3 class="tm-sub"><svg><use href="#i-time"/></svg>الخطوات</h3><ol class="fq-steps">${c.st.map(s => `<li class="fq-step fq-c"><b>${s.t}</b><p>${esc(s.x)}</p></li>`).join('')}</ol>` : '';
  const khHtml = c => c.kh ? `<h3 class="tm-sub"><svg><use href="#i-ulum"/></svg>الخلاف المعتبر بين المذاهب</h3><div class="fq-khs">${c.kh.map(k => `<section class="fq-kh fq-c"><h4>${k.t}</h4><p class="muted small">${esc(k.n)}</p>
    <ul>${k.p.map(([w, v]) => `<li><b>${w}</b><span>${esc(v)}</span></li>`).join('')}</ul></section>`).join('')}</div>
    <p class="muted small fq-khn">نعرض أقوال المذاهب كما هي دون ترجيح من عندنا، فاسأل أهل العلم في بلدك لمعرفة المعمول به عندكم.</p>` : '';
  const body = c => { const hs = D.h.filter(h => h.ch === c.id), qs = D.q.filter(q => q.ch === c.id);
    return `${stepsHtml(c)}${c.kh && c.kh.length ? khHtml(c) : ''}
      ${c.ay.length ? `<h3 class="tm-sub"><svg><use href="#i-book"/></svg>من القرآن الكريم</h3><div class="tm-grid">${c.ay.map(ayCard).join('')}</div>` : ''}
      ${hs.length ? `<h3 class="tm-sub"><svg><use href="#i-scroll"/></svg>من السنة الصحيحة</h3><div class="tm-grid">${hs.map(hCard).join('')}</div>` : ''}
      ${qs.length ? `<h3 class="tm-sub"><svg><use href="#i-book"/></svg>من أقوال المفسرين</h3><div class="tm-grid">${qs.map(qCard).join('')}</div>` : ''}`; };
  const cats = D.cats;
  V(`<div class="stack ulum tm fq ${CFG.cls}">
    <section class="u-hero tm-hero"><span class="eyebrow">${CFG.eyebrow}</span><h1>${CFG.h1}</h1><p class="lead">${CFG.lead}</p>
      <div class="tm-stats">${CFG.stats.map(([v, l]) => `<span><b class="num">${n(v)}</b> <span>${l}</span></span>`).join('')}</div></section>
    <div class="tm-warn" role="note"><b>${CFG.note[0]}</b><p>${CFG.note[1]}</p></div>
    <section class="panel fq-tools"><h2>${CFG.searchLbl}</h2><p class="muted small">${CFG.searchHint}</p>
      <input type="search" id="fqs" class="field" placeholder="${CFG.searchLbl}…" aria-label="${CFG.searchLbl}" autocomplete="off">
      <p class="fq-cnt muted small" id="fqc" aria-live="polite" hidden></p>
      <div class="tm-chips" role="group"><button type="button" class="tm-chip on" data-fqc="">الكل</button>${cats.map(([id, t]) => `<button type="button" class="tm-chip" data-fqc="${id}">${t}</button>`).join('')}</div></section>
    ${CFG.cross ? `<a class="panel fq-cross" href="#${CFG.cross[2]}"><span><b>${CFG.cross[0]}</b><small>${CFG.cross[1]}</small></span><em>${CFG.cross[3]}</em></a>` : ''}
    <nav class="panel u-index" aria-label="الفهرس"><h2>الفهرس</h2><ol id="fqx">${D.ch.map((c, i) => `<li data-c="${c.c}"><a href="#${key}" data-fqj="${c.id}"><span class="u-n">${n(i + 1)}</span>${c.t}</a></li>`).join('')}</ol></nav>
    ${D.ch.map((c, i) => `<details class="u-ch panel tm-ch" id="fq-${c.id}" data-c="${c.c}"${i === 0 ? ' open' : ''}><summary><span class="u-n">${n(i + 1)}</span><span class="u-t">${c.t}</span></summary>
      <div class="u-body stack tight"><p class="u-intro">${esc(c.d)}</p>${body(c)}</div></details>`).join('')}
    <p class="fq-empty panel" id="fqe" hidden>لا نتائج</p>
    <p class="muted small">${CFG.foot}</p>
  </div>`);
  const go = el => { if (!el) return; const d = el.closest('details'); if (d) d.open = true; el.scrollIntoView({ behavior: 'smooth', block: 'start' }); };
  $$('[data-fqj]').forEach(a => a.onclick = e => { e.preventDefault(); go($('#fq-' + a.dataset.fqj)); });
  const NORM = s => String(s).replace(/[ً-ٰٟۖ-ۭـ]/g, '').replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').toLowerCase();
  let cat = '';
  const apply = () => {
    const qv = NORM($('#fqs').value.trim()); let shown = 0;
    $$('details.tm-ch').forEach(d => {
      const inCat = !cat || d.dataset.c === cat; let hits = 0;
      d.querySelectorAll('.fq-c').forEach(el => { const ok = !qv || NORM(el.textContent).includes(qv); el.hidden = !ok; if (ok) hits++; });
      const intro = !qv || NORM(d.querySelector('summary').textContent + ' ' + d.querySelector('.u-intro').textContent).includes(qv);
      const vis = inCat && (!qv || hits > 0 || intro);
      d.hidden = !vis; if (vis) { shown++; if (qv) d.open = true; }
      d.querySelectorAll('.tm-sub').forEach(h => { const g = h.nextElementSibling; h.hidden = !!qv && !(g && g.querySelector('.fq-c:not([hidden])')); });
      d.querySelectorAll('.fq-khn').forEach(p => { p.hidden = !!qv && !d.querySelector('.fq-kh:not([hidden])'); });
    });
    $$('#fqx li').forEach(li => { const d = $('#fq-' + li.querySelector('a').dataset.fqj); li.hidden = d.hidden; });
    const c = $('#fqc'); c.hidden = !qv; if (qv) c.textContent = shown ? `${n(shown)} / ${n(D.ch.length)}` : '';
    $('#fqe').hidden = shown > 0;
  };
  $('#fqs').oninput = apply;
  $$('[data-fqc]').forEach(b => b.onclick = () => { cat = b.dataset.fqc; $$('[data-fqc]').forEach(x => x.classList.toggle('on', x === b)); apply(); });
};
